// Üretilen dosya: tool/ozgun/uret.py. Biyoloji ve Yaşam Bilimleri · Evrimsel biyoloji ve popülasyon genetiği: doğal seçilim biçimleri, Hardy-Weinberg dengesi, genetik sürüklenme ve türleşme mekanizmaları (orta).
const ozBiology17Orta = <(String, String, List<String>, String)>[
  ('Hardy-Weinberg dengesindeki bir bitki popülasyonunda çekinik alel frekansı (q) 0,3 olarak ölçülmüştür. Bu popülasyonda heterozigot genotipli bitkilerin yüzdesi kaçtır?', '%42', ['%49', '%21', '%9'], 'p + q = 1 olduğundan p = 0,7 bulunur; heterozigot oranı 2pq = 2 × 0,7 × 0,3 = 0,42 yani %42\'dir.'),
  ('Dengedeki 1000 kişilik bir insan popülasyonunda otozomal çekinik bir özelliği fenotipinde gösteren 160 birey bulunmaktadır. Bu popülasyonda baskın alelin (p) frekansı kaçtır?', '0,6', ['0,4', '0,16', '0,84'], 'Çekinik fenotip oranı q² = 160 / 1000 = 0,16 olduğundan q = 0,4 ve p = 1 - 0,4 = 0,6 olarak hesaplanır.'),
  ('Hardy-Weinberg dengesindeki bir kelebek popülasyonunda kanat rengini belirleyen baskın fenotipli bireylerin oranı %91\'dir. Buna göre çekinik alelin gen havuzundaki frekansı kaçtır?', '0,3', ['0,09', '0,7', '0,42'], 'Baskın fenotip (p² + 2pq) %91 ise çekinik fenotip q² = %9 yani 0,09\'dur; buradan q = 0,3 bulunur.'),
  ('Bir popülasyonda yapılan genetik taramada AA genotipli 180, Aa genotipli 240 ve aa genotipli 80 birey saptanmıştır. Bu popülasyonun p alel frekansı ve denge durumu için ne söylenebilir?', 'p = 0,6 olup popülasyon Hardy-Weinberg dengesindedir', ['p = 0,6 olup popülasyon dengede değildir', 'p = 0,36 olup popülasyon Hardy-Weinberg dengesindedir', 'p = 0,4 olup popülasyon dengede değildir'], 'Toplam 500 bireyde A aleli sayısı (2×180 + 240) = 600, toplam alel 1000\'dir; p = 0,6 ve q = 0,4 olur. Beklenen oranlar p²=0,36 (180), 2pq=0,48 (240), q²=0,16 (80) gözlenenle tam uyumludur.'),
  ('Diploit 200 bireyden oluşan bir böcek popülasyonunda GG genotipli 90, Gg genotipli 40 ve gg genotipli 70 birey sayılmıştır. Bu popülasyonda G alelinin frekansı kaçtır ve popülasyon dengede midir?', '0,55; popülasyon Hardy-Weinberg dengesinde değildir', ['0,55; popülasyon Hardy-Weinberg dengesindedir', '0,45; popülasyon Hardy-Weinberg dengesinde değildir', '0,65; popülasyon Hardy-Weinberg dengesindedir'], 'Toplam 400 alelin (2×90 + 40) = 220 tanesi G alelidir; p = 220/400 = 0,55 ve q = 0,45 olur. Dengede olsaydı heterozigot sayısı 2 × 0,55 × 0,45 × 200 = 99 olmalıydı, 40 olduğu için dengede değildir.'),
  ('Bir popülasyonda baskın bir alelin frekansının p = 0,2 olması durumunda aşağıdakilerden hangisi kesinlikle doğrudur?', 'Baskın alel gen havuzunda çekinik alelden daha az bulunur', ['Baskın alel zamanla frekansını artırarak 0,5\'in üzerine çıkar', 'Popülasyondaki bireylerin çoğunluğu baskın fenotiplidir', 'Heterozigot bireylerin oranı homozigot çekiniklerden fazladır'], 'Bir alelin baskın olması onun popülasyonda yaygın olacağı anlamına gelmez; p = 0,2 iken q = 0,8\'dir ve baskın fenotip (0,04 + 0,32 = %36) azınlıktadır.'),
  ('Eksik baskınlığın görüldüğü akşamsefası bitkilerinde kırmızı (RR), pembe (Rr) ve beyaz (rr) çiçekli bireyler bulunur. 500 bitkilik bir popülasyonda 125 kırmızı, 250 pembe ve 125 beyaz çiçekli bitki varsa r alelinin frekansı kaçtır?', '0,5', ['0,25', '0,75', '0,125'], 'Toplam 1000 alel içinde beyazlardan 250, pembelerden 250 olmak üzere 500 adet r aleli vardır; q = 500/1000 = 0,5\'tir.'),
  ('Eş baskın MN kan grubu sistemine sahip dengedeki bir insan popülasyonunda M kan gruplu bireylerin oranı %36 olarak belirlenmiştir. Bu popülasyonda MN kan gruplu bireylerin yüzdesi kaçtır?', '%48', ['%64', '%16', '%24'], 'MM genotipi p² = 0,36 olduğundan M aleli frekansı p = 0,6 ve N aleli frekansı q = 0,4 olur; MN genotipi 2pq = 2 × 0,6 × 0,4 = 0,48 (%48) bulunur.'),
  ('Bir araştırmacı, izole bir göldeki balık popülasyonunda belirli bir lokustaki alel frekanslarının 10 nesil boyunca değişmediğini saptamıştır. Yalnızca bu veriye dayanarak aşağıdaki yargılardan hangisine kesin olarak ulaşılabilir?', 'İncelenen karakter bakımından popülasyonda bu süreçte evrim gerçekleşmemiştir', ['Gölde hiçbir gen lokusunda mutasyon meydana gelmemiştir', 'Popülasyondaki balık sayısı sonsuz büyüklüğe ulaşmıştır', 'İncelenen gen balıkların hayatta kalma başarısını artırmaktadır'], 'Mikroevrim, popülasyonun gen havuzundaki alel frekanslarının nesiller içinde değişmesidir; incelenen lokusta frekans değişmemişse o karakter için evrim olmamıştır.'),
  ('Hardy-Weinberg dengesindeki iki alelli bir popülasyonda heterozigot bireylerin oranı (2pq) en fazla hangi sayısal değere ulaşabilir?', '0,50', ['0,75', '0,66', '1,00'], 'p + q = 1 iken 2pq çarpımı p = 0,5 ve q = 0,5 olduğunda maksimum değerini alır: 2 × 0,5 × 0,5 = 0,50 (%50).'),
  ('Bir bitki popülasyonunda çiçeklerin sürekli kendi kendine tozlaşması (öz döllenme) gen havuzunu ve genotip frekanslarını nasıl etkiler?', 'Alel frekanslarını değiştirmez ancak homozigot bireylerin oranını artırır', ['Çekinik alelin frekansını hızla sıfıra indirerek baskın aleli sabitler', 'Heterozigot bireylerin oranını her nesilde iki katına çıkarır', 'Hem alel hem de genotip frekanslarını Hardy-Weinberg dengesinde tutar'], 'Öz döllenme (akraba evliliği gibi) rastgele olmayan eşleşmedir; tek başına p ve q değerlerini değiştirmez fakat her nesilde heterozigotluğu yarıya indirip homozigotluğu artırır.'),
  ('Hayvanlarda bireylerin fenotipik olarak kendilerine benzeyen eşleri tercih etmesi (pozitif asortatif eşleşme) popülasyonda hangi sonuca yol açar?', 'Beklenen Hardy-Weinberg oranına kıyasla homozigot sıklığının artmasına', ['Gen havuzundaki toplam alel çeşitliliğinin yeni mutasyonlarla artmasına', 'Baskın alelin frekansının çekinik alele göre hızla yükselmesine', 'Heterozigot genotipli bireylerin oranının %50\'nin üzerine çıkmasına'], 'Benzer fenotiplerin eşleşmesi aynı alelleri taşıyan bireyleri bir araya getirdiğinden heterozigotları azaltır, homozigot genotiplerin oranını artırır.'),
  ('Hardy-Weinberg ilkelerine göre yalnızca somatik (vücut) hücrelerde meydana gelen mutasyonların popülasyonun gen havuzunu değiştirmemesinin nedeni nedir?', 'Eşeyli üreyen canlılarda somatik mutasyonların gametlerle yavrulara aktarılmaması', ['Vücut hücrelerindeki DNA moleküllerinin mutasyon geçirme yeteneğinin bulunmaması', 'Somatik mutasyonların her zaman DNA onarım enzimleriyle eksiksiz düzeltilmesi', 'Bu tür mutasyonların yalnızca homozigot çekinik bireylerde ortaya çıkması'], 'Popülasyonun gelecek nesildeki gen havuzunu üreme hücreleri (gametler) oluşturur; vücut hücrelerindeki değişimler kalıtsal değildir.'),
  ('Mutasyonların tek başına bir nesilde popülasyonun alel frekanslarında çok büyük sıçramalar yaratmamasının ancak evrim için vazgeçilmez olmasının nedeni aşağıdakilerden hangisidir?', 'Mutasyon hızlarının düşük olması fakat doğal seçilime ham madde sağlaması', ['Mutasyonların yalnızca küçük popülasyonlarda meydana gelebilmesi', 'Oluşan tüm mutasyonların bireye anında yüksek üreme avantajı kazandırması', 'Mutasyonların ileri ve geri yönde her zaman eşit hızda gerçekleşmesi'], 'Tek bir lokusta mutasyon hızı genellikle 10⁻⁵ ile 10⁻⁶ gibi düşüktür; ancak genetik çeşitliliğin nihai kaynağı olarak seçilime zemin hazırlar.'),
  ('Dengedeki bir koyun sürüsünde beyaz yün aleli (B), siyah yün aleline (b) tam baskındır. Sürüdeki 400 koyundan 36 tanesi siyah yünlü olduğuna göre, sürüde kaç adet homozigot beyaz yünlü koyun bulunması beklenir?', '196', ['168', '364', '280'], 'q² = 36 / 400 = 0,09 olduğundan q = 0,3 ve p = 0,7 bulunur. Homozigot beyaz (BB) oranı p² = 0,49\'dur; 400 × 0,49 = 196 koyun eder.'),
  ('Hardy-Weinberg dengesindeki bir popülasyonda homozigot baskın bireylerin sayısı, homozigot çekinik bireylerin sayısının 9 katıdır. Bu popülasyonda çekinik alelin (q) frekansı kaçtır?', '0,25', ['0,10', '0,75', '0,33'], 'p² = 9q² eşitliğinde her iki tarafın karekökü alındığında p = 3q elde edilir. p + q = 1 olduğundan 3q + q = 1 ve 4q = 1, yani q = 0,25 bulunur.'),
  ('Bir popülasyonda sadece eşeyli üreme (mayoz bölünme ve rastgele döllenme) gerçekleşiyor ve hiçbir evrimsel faktör etki etmiyorsa gen havuzunda nasıl bir değişim gözlenir?', 'Alel frekansları değişmez, yalnızca mevcut aleller yeni kombinasyonlar oluşturur', ['Her kuşakta çekinik aleller yarıya inerken baskın aleller iki katına çıkar', 'Mayoz sırasındaki krossing over nedeniyle alel frekansları rastgele dalgalanır', 'Popülasyondaki tüm bireyler birkaç nesil içinde genetik olarak özdeş hale gelir'], 'Tek başına eşeyli üreme ve rekombinasyon Hardy-Weinberg dengesini bozmaz; alel sıklıklarını sabit tutarak bireysel çeşitlilik sağlar.'),
  ('Tat alma testi yapılan dengedeki 800 kişilik bir öğrenci grubunda PTC maddesinin acı tadını alamayan (çekinik fenotipli) 288 kişi tespit edilmiştir. Tat alabilen öğrencilerin kaç tanesinin homozigot baskın olması beklenir?', '128', ['384', '512', '200'], 'q² = 288 / 800 = 0,36 olduğundan q = 0,6 ve p = 0,4 bulunur. Homozigot baskın (p²) oranı = 0,16\'dır; 800 × 0,16 = 128 öğrenci homozigot baskındır.'),
  ('Bir popülasyonda belirli bir gen lokusu için "alelin sabitlenmesi" (fiksasyon) ifadesi ne anlama gelir?', 'İlgili alelin frekansının 1\'e ulaşması ve diğer alternatif alellerin tamamen kaybolması', ['Baskın ve çekinik alel frekanslarının 0,5 değerinde birbirine eşitlenmesi', 'Popülasyonun Hardy-Weinberg dengesine girerek genotip oranlarını koruması', 'Mutasyon hızının doğal seçilim hızıyla tam olarak dengelenmesi'], 'Fiksasyon, bir lokusta tek bir alelin %100 (p = 1, q = 0) oranına ulaşarak o gen için polimorfizmin sona ermesidir.'),
  ('Bir kelebek popülasyonunda 300 birey incelenmiş; A1A1 genotipli 120, A1A2 genotipli 120 ve A2A2 genotipli 60 birey bulunmuştur. A2 alelinin bu popülasyondaki frekansı kaçtır?', '0,4', ['0,2', '0,6', '0,5'], 'Toplam 600 alel içinde A2 aleli sayısı = 120 + (2 × 60) = 240 adettir. Frekans q = 240 / 600 = 0,4 olarak bulunur.'),
  ('Rastgele eşleşmenin olmadığı ve yakın akrabalar arası evliliklerin (soy içi üreme) çok sık yapıldığı kapalı bir insan topluluğunda otozomal çekinik hastalıkların daha sık görülmesinin nedeni nedir?', 'Alel frekansları değişmese bile homozigot çekinik (q²) genotip oranının artması', ['Akraba evliliklerinin sağlıklı genleri bozarak doğrudan yeni mutasyonlar üretmesi', 'Çekinik alelin gen havuzundaki toplam oranının (q) her nesilde katlanarak artması', 'Baskın alellerin mayoz bölünme sırasında gametlere geçme olasılığının düşmesi'], 'Soy içi üreme (inbreeding) doğrudan p ve q değerlerini değiştirmez ancak ortak atadan gelen çekinik alellerin birleşme ihtimalini artırarak homozigot çekinik hasta sayısını yükseltir.'),
  ('Dengedeki bir popülasyonda bir genin baskın alel frekansı çekinik alel frekansının 4 katıdır. Bu popülasyondan rastgele seçilen bir bireyin heterozigot olma olasılığı yüzde kaçtır?', '%32', ['%16', '%64', '%20'], 'p = 4q ve p + q = 1 olduğundan 5q = 1, yani q = 0,2 ve p = 0,8 bulunur. Heterozigot olma olasılığı 2pq = 2 × 0,8 × 0,2 = 0,32 (%32) olur.'),
  ('Erkek tavus kuşlarının gösterişli kuyruklarına göre dişiler tarafından seçilmesi (eşeysel seçilim), Hardy-Weinberg dengesinin hangi temel koşulunu doğrudan ihlal eder?', 'Hem rastgele eşleşme hem de doğal seçilimin olmaması koşullarını', ['Popülasyonun dışarıya kapalı olması ve göç yaşanmaması koşulunu', 'Genlerde ileri veya geri yönde mutasyon gerçekleşmemesi koşulunu', 'Popülasyon büyüklüğünün sürüklenmeyi önleyecek kadar geniş olmasını'], 'Eş seçimi rastgele eşleşmeyi bozar ve bazı genotiplerin daha fazla döl vermesine yol açtığı için seçilim baskısı yaratır.'),
  ('Hardy-Weinberg dengesindeki 2500 bireylik bir kemirgen popülasyonunda çekinik fenotipli 900 birey sayılmıştır. Popülasyondaki toplam baskın alel sayısı (frekansı değil, mutlak kopya sayısı) kaçtır?', '2000', ['1000', '3000', '1600'], 'q² = 900 / 2500 = 0,36 ise q = 0,6 ve p = 0,4\'tür. Diploit 2500 bireyde toplam 5000 alel bulunur; baskın alel sayısı = 5000 × 0,4 = 2000 adettir.'),
  ('Bir popülasyonda yönlü doğal seçilim (directional selection) homozigot çekinik fenotipe karşı işliyorsa nesiller ilerledikçe p ve q değerlerinde nasıl bir eğilim görülür?', 'p değeri 1\'e doğru yaklaşırken q değeri giderek azalır fakat hızla sıfırlanmaz', ['q değeri hızla 1\'e yükselirken p değeri birkaç nesilde tamamen yok olur', 'p ve q değerleri birbirine yaklaşarak 0,50 noktasında kalıcı denge kurar', 'Genotip frekansları değişse bile p ve q alel frekansları sabit kalır'], 'Çekinik fenotipe karşı seçilim q alelini azaltır, p alelini artırır; ancak azalan q aleli heterozigotlarda gizlendiği için sıfırlanması çok yavaşlar.'),
  ('Dengedeki bir çiçek popülasyonunda homozigot baskın (KK) ve homozigot çekinik (kk) bireylerin genotip frekansları birbirine eşittir. Bu popülasyonda heterozigot (Kk) bireylerin oranı kaçtır?', '0,50', ['0,25', '0,33', '0,75'], 'p² = q² olduğundan p = q olur. p + q = 1 eşitliğinden p = 0,5 ve q = 0,5 bulunur; buradan 2pq = 2 × 0,5 × 0,5 = 0,50 elde edilir.'),
  ('Gregor Mendel\'in kalıtım ilkelerinin keşfinden sonra "baskın özelliklerin zamanla popülasyondaki tüm bireyleri ele geçireceği ve çekinik özelliklerin kaybolacağı" yönündeki yanlış inanışı hangi bilimsel model çürütmüştür?', 'Hardy-Weinberg denge prensibi', ['Lamarck\'ın kazanılmış karakterler hipotezi', 'Kromozomal krossing over teorisi', 'Hücre teorisinin modern yorumu'], 'Hardy ve Weinberg, evrimsel kuvvetler olmadığında baskın bir alelin sırf baskın olduğu için sıklığının artmayacağını (p² + 2pq + q² = 1) matematiksel olarak kanıtlamıştır.'),
  ('Bir göldeki kurbağa popülasyonunda iki alelli bir enzim lokusu incelenmiş ve F1A1 genotipli kurbağaların tüm popülasyonun %48\'ini oluşturduğu, popülasyonun dengede olduğu belirlenmiştir. Buna göre homozigot genotiplerden birinin oranı aşağıdakilerden hangisi OLABİLİR?', '%36', ['%25', '%49', '%81'], '2pq = 0,48 ise pq = 0,24 ve p + q = 1\'dir. Bu denklemin kökleri 0,6 ve 0,4\'tür. Dolayısıyla homozigot oranları p² ve q² yalnızca %36 (0,6²) veya %16 (0,4²) olabilir.'),
  ('Doğal bir orman ekosisteminde yaşayan geyik popülasyonunun "tüm gen lokusları bakımından" aynı anda kusursuz Hardy-Weinberg dengesinde bulunması neden beklenmez?', 'Bazı lokuslar nötr kalırken diğer lokusların çevresel seçilim baskısına maruz kalması', ['Geyiklerin diploit kromozom sayısının matematiksel hesaplamaya izin vermemesi', 'Orman ekosistemlerinde eşeyli üremenin alel frekanslarını her yıl sıfırlaması', 'Mendel yasalarının yalnızca tek hücreli organizmalar için geçerli olması'], 'Doğal seçilim organizmanın çevreyle etkileşen belirli fenotiplerine (dolayısıyla belirli lokuslara) etki ederken nötr lokuslara etki etmeyebilir; ayrıca sonlu nüfus ve göç de mutlak dengeyi engeller.'),
  ('Çeşitlendirici (dallandırıcı) doğal seçilimin uzun süre etkili olduğu bir popülasyonda fenotip dağılımında nasıl bir değişim gözlenir?', 'Ortalama fenotipli bireyler azalırken her iki uçtaki fenotiplerin sıklığı artar', ['Tek bir uç fenotip hızla artarken diğer tüm fenotipler gen havuzundan silinir', 'Tüm bireyler tek bir ortalama fenotip etrafında dar bir çan eğrisinde toplanır', 'Fenotip çeşitliliği tamamen ortadan kalkarak genetik klonlama gerçekleşir'], 'Dallandırıcı seçilimde ara formlar dezavantajlı, her iki uçtaki ekstrem fenotipler avantajlı olduğundan popülasyon iki farklı fenotipik gruba doğru ayrışır.'),
  ('Dengedeki bir popülasyonda iki alelli bir gen için homozigot baskın bireylerin oranı %64\'tür. Bu popülasyondan rastgele seçilen 500 bireyden kaç tanesinin çekinik aleli genotipinde (homozigot veya heterozigot olarak) taşıması beklenir?', '180', ['20', '160', '320'], 'p² = 0,64 ise homozigot baskın (AA) olmayan herkes (Aa + aa) en az bir çekinik alel taşır. Bu oran 1 - 0,64 = 0,36\'dır; 500 × 0,36 = 180 birey eder.'),
  ('Bir tarım zararlısı böcek popülasyonuna düzenli olarak aynı kimyasal böcek ilacı (pestisit) uygulandığında birkaç yıl içinde ilaca dirençli böceklerin oranının %2\'den %85\'e çıkması nasıl açıklanır?', 'Önceden var olan direnç alelinin ilaç baskısı altında doğal seçilimle sıklığının artmasıyla', ['İlacın her bir böcekte hayatta kalmak için bilinçli olarak direnç mutasyonu oluşturmasıyla', 'Böceklerin ilaca alışarak kazandıkları vücut bağışıklığını yavrularına aktarmasıyla', 'Hardy-Weinberg dengesinin ilaçlı ortamda tüm alel oranlarını sabitlemesiyle'], 'İlaç direnç mutasyonunu yoktan var etmez; gen havuzunda zaten düşük frekansta bulunan dirençli aleli taşıyanlar hayatta kalıp üreyerek alel frekansını artırır.'),
  ('X kromozomuna bağlı baskın bir özellik, dengedeki bir popülasyonda erkeklerin %30\'unda görülmektedir. Aynı özelliğin bu popülasyondaki kadınlarda görülme yüzdesi kaçtır?', '%51', ['%30', '%9', '%42'], 'Erkeklerde baskın fenotip oranı doğrudan p = 0,30 değerini verir; buradan q = 0,70 olur. Kadınlarda baskın fenotip (p² + 2pq veya 1 - q²) = 1 - 0,49 = 0,51 yani %51\'dir.'),
  ('Bir popülasyonda "frekansa bağlı seçilim" (frequency-dependent selection) işlediğinde nadir bulunan fenotipler avantaj kazanıyorsa (negatif frekansa bağlı seçilim) gen havuzunda ne beklenir?', 'Nadir aleller elenmek yerine korunur ve popülasyondaki genetik çeşitlilik sürdürülür', ['En yaygın olan alel hızla %100 oranına ulaşarak popülasyonda sabitlenir', 'Popülasyondaki tüm bireyler birkaç kuşak içinde kısırlaşarak soy tükenir', 'Alel frekansları hiçbir dalgalanma göstermeden tek bir noktada donup kalır'], 'Avcıların en yaygın av tipine odaklanması gibi durumlarda nadir fenotipler avantaj kazanır, çoğaldıkça avantajını kaybeder; böylece polimorfizm korunur.'),
  ('Dengedeki bir popülasyonda çekinik bir karakteri gösteren bireylerin tüm popülasyona oranı 1/16\'dır. Bu popülasyonda baskın fenotipli bireylerin oranı kaçtır?', '15 / 16', ['3 / 4', '9 / 16', '6 / 16'], 'Toplam fenotip oranları toplamı 1\'dir. Çekinik fenotip (q²) = 1/16 ise, geri kalan tüm bireyler baskın fenotiplidir (p² + 2pq = 1 - 1/16 = 15/16).'),
  ('Aşağıdakilerden hangisi genetik sürüklenmenin bir popülasyon üzerindeki karakteristik sonuçlarından biri DEĞİLDİR?', 'Bireylerin çevreye olan kalıtsal uyumunu (adaptasyonunu) düzenli olarak artırması', ['Popülasyon içindeki genel genetik çeşitliliği zamanla azaltması', 'Alel frekanslarının nesiller boyunca öngörülemez şekilde dalgalanmasına yol açması', 'Zararlı alellerin bile şans eseri popülasyonda sabitlenmesine neden olabilmesi'], 'Tutarlı olarak adaptasyon sağlayan tek evrimsel mekanizma doğal seçilimdir; genetik sürüklenme rastgeledir ve uyumu artırma zorunluluğu yoktur.'),
  ('Kuzey deniz fillerinin 19. yüzyılda aşırı avlanma nedeniyle sayılarının 20 bireye kadar düşmesi, koruma altına alındıktan sonra sayılarının 100 binin üzerine çıkmasına rağmen genetik çeşitliliklerinin hâlâ çok düşük olması hangi kavramla açıklanır?', 'Geçmişte yaşanan şiddetli darboğaz etkisinin gen havuzundaki alelleri silmiş olmasıyla', ['Birey sayısı arttıkça popülasyonda ileri yönlü mutasyonların tamamen durmasıyla', 'Koruma altındaki hayvanlarda eşeyli üremenin çeşitlilik yaratma yeteneğini yitirmesiyle', 'Deniz fillerinin Hardy-Weinberg dengesine girerek yalnızca baskın alelleri korumasıyla'], 'Nüfus sayısı eski haline dönse bile darboğaz sırasında kaybolan aleller yalnızca çok yavaş işleyen yeni mutasyonlarla geri kazanılabilir.'),
  ('Atlas Okyanusu\'ndaki küçük Tristan da Cunha adasına yerleşen 15 kişilik kurucu gruptan bir kişinin nadir görülen çekinik bir göz hastalığı (retinitis pigmentosa) taşıyıcısı olması nedeniyle, adadaki hastalık sıklığının dünya ortalamasının çok üzerinde çıkması neyin örneğidir?', 'Kurucu etkisinin nadir alelleri yeni kolonide yüksek frekansa taşımasının', ['Ada ikliminin insanlarda göz genlerini bozan özel mutasyonları tetiklemesinin', 'Göz hastalığı alelinin ada ortamında bireylere yüksek üreme avantajı sağlamasının', 'Komşu kıtalardan adaya yoğun gen akışının sürekli devam etmesinin'], 'Kurucu grupta tesadüfen bulunan nadir bir alel, küçük başlangıç nüfusunda yüksek orana (1/30 alel gibi) sahip olarak yeni popülasyonda yaygınlaşır.'),
  ('Bir adada yaşayan 800 bireylik kuş popülasyonunda A alelinin frekansı p = 0,7\'dir. Anakara üzerinden adaya tamamı homozigot çekinik (aa) olan 200 kuş göç edip popülasyona katılırsa yeni oluşan gen havuzunda A alelinin frekansı kaç olur?', '0,56', ['0,60', '0,35', '0,44'], 'Mevcut 800 bireyde 1600 alelin 1600 × 0,7 = 1120 tanesi A alelidir. Gelen 200 birey (400 alel) hiç A aleli getirmez (aa). Yeni toplam 2000 alelde 1120 A aleli vardır: 1120 / 2000 = 0,56.'),
  ('Genetik sürüklenme ile doğal seçilim karşılaştırıldığında aşağıdakilerden hangisi her iki mekanizma için de ORTAK bir özelliktir?', 'Popülasyonun alel frekanslarını değiştirerek Hardy-Weinberg dengesini bozmaları', ['Yalnızca çevreye en iyi uyum sağlayan avantajlı alellerin sıklığını artırmaları', 'Etkilerinin yalnızca on binlerce bireyden oluşan dev popülasyonlarda görülmesi', 'Gen havuzuna daha önce hiç var olmayan yepyeni aleller kazandırmaları'], 'Hem doğal seçilim hem de genetik sürüklenme alel sıklıklarını değiştirerek mikroevrime yol açar ve Hardy-Weinberg dengesini bozar.'),
  ('Toplam 100 bireyden oluşan iki ayrı memeli sürüsünden birincisinde 50 erkek ve 50 dişi üremeye katılırken, ikincisinde harem sistemi nedeniyle yalnızca 2 baskın erkek ile 98 dişi üremeye katılmaktadır. Genetik sürüklenme açısından hangi sürü daha büyük risk altındadır?', 'Üremeye yalnızca 2 erkeğin katıldığı ikinci sürüde sürüklenme çok daha şiddetlidir', ['Toplam birey sayıları 100 olduğu için her iki sürüde sürüklenme hızı eşittir', 'Dişi sayısı daha fazla olduğu için ikinci sürüde genetik çeşitlilik daha iyi korunur', 'Birinci sürüde cinsiyet oranı eşit olduğu için alel kaybı daha hızlı gerçekleşir'], 'Cinsiyet oranının üremede aşırı dengesiz olması etkili popülasyon büyüklüğünü (Ne = 4NmNf / (Nm+Nf) ≈ 7,8) çok düşürür ve genetik sürüklenmeyi hızlandırır.'),
  ('Çita (Acinonyx jubatus) popülasyonlarında bireyler arasında doku ve deri nakli yapıldığında bağışıklık sisteminin dokuyu reddetmemesi popülasyon genetiği açısından nasıl yorumlanır?', 'Geçmişteki darboğazlar nedeniyle bireylerin genetik olarak birbirine aşırı benzemesiyle', ['Çitalarda bağışıklık sistemini yöneten genlerin hiçbir zaman bulunmamasıyla', 'Yüksek gen akışı sayesinde çitaların sürekli yeni doku alelleri kazanmasıyla', 'Hardy-Weinberg dengesinin tüm etçil memelilerde doku uyumunu sağlamasıyla'], 'Buzul Çağı\'nda yaşanan ağır darboğaz etkisi çitaların MHC (doku uygunluk) gen çeşitliliğini neredeyse sıfırlamış, alakasız bireyleri bile ikiz benzeri yakınlığa getirmiştir.'),
  ('Karayolları ve barajlarla yaşam alanları küçük, kopuk parçalara bölünen (habitat parçalanması) yaban hayatı popülasyonlarını kurtarmak için "ekolojik koridorlar" inşa edilmesinin popülasyon genetiğindeki temel amacı nedir?', 'İzole parçalar arasında gen akışı sağlayarak soy içi üremeyi ve sürüklenmeyi azaltmak', ['Hayvanların avcılardan kaçarken daha fazla kalori harcayarak güçlenmesini sağlamak', 'Popülasyonlardaki doğal seçilimi tamamen durdurarak mutasyon hızını artırmak', 'Farklı türlerin birbirleriyle melezleşerek kısır bireyler oluşturmasını teşvik etmek'], 'Ekolojik geçiş koridorları parçalanmış küçük alt popülasyonlar arasında birey geçişine (gen akışına) izin vererek genetik çeşitlilik kaybını ve soy içi üreme çöküşünü önler.'),
  ('Öte yandan, küresel ısınma nedeniyle hızla ısınan kuzeydeki bir bitki popülasyonuna daha sıcak güney enlemlerindeki türdeşlerinden polen gelmesi (gen akışı) nasıl bir sonuç doğurabilir?', 'Sıcaklığa dayanıklılık sağlayan yararlı alelleri taşıyarak popülasyonun uyumuna katkıda bulunur', ['Popülasyondaki tüm bireylerin genetik çeşitliliğini anında sıfıra indirir', 'Hardy-Weinberg dengesini koruyarak alel frekanslarının değişmesini engeller', 'Güneydeki polenler yalnızca çekinik alel taşıdığı için kuzey bitkilerini kısırlaştırır'], 'Gen akışı her zaman uyumu bozmaz; değişen çevre koşullarında komşu popülasyonlardan uyumlu alellerin gelmesi (adaptif gen akışı) popülasyonun kurtulmasını sağlayabilir.'),
  ('İzole bir gölette yaşayan 25 bireylik küçük bir balık popülasyonunda yalnızca 1 birey nadir bir A2 alelini heterozigot (A1A2) olarak taşımakta, diğer 24 birey ise A1A1 genotipindedir. Bu popülasyonda A2 alelinin başlangıç frekansı kaçtır?', '0,02', ['0,04', '0,01', '0,08'], '25 diploit bireyde toplam 25 × 2 = 50 alel kopyası bulunur. Yalnızca bir heterozigot bireyde 1 adet A2 aleli olduğundan frekans 1 / 50 = 0,02\'dir.'),
  ('Bir ormanda çıkan büyük yangında ağaçların %95\'i rastgele yanarak kül olmuş, yalnızca vadinin kuytu bir köşesindeki %5\'lik ağaç grubu yangından kurtulmuştur. Kurtulan ağaçların gen havuzu için aşağıdakilerden hangisi en doğrudur?', 'Yangına dayanıklılıktan ziyade konum şansıyla kurtuldukları için darboğaz etkisi yaşanmıştır', ['Kurtulan ağaçların tamamı ateşe dayanıklı üstün genler taşıdığı için doğal seçilim olmuştur', 'Ağaçların sayısı azaldığı için geri kalan bireylerde alel çeşitliliği eskisinden fazla artmıştır', 'Yangın somatik dokuları etkilediği için popülasyonun alel frekansları hiç değişmemiştir'], 'Afet bireyleri genotiplerine göre seçmeden rastgele yok ettiğinden bu durum doğal seçilim değil, alel oranlarını şansla değiştiren darboğaz etkisidir.'),
  ('Dengedeki büyük bir anakara kertenkele popülasyonunda yeşil sırt aleli (p = 0,9) ve kahverengi sırt aleli (q = 0,1) bulunmaktadır. Fırtınayla sürüklenen kütük üzerindeki 4 kertenkele (2 tanesi Yy, 2 tanesi yy) boş bir adaya ulaşıp yeni popülasyon kurmuştur. Kurucu grupta kahverengi alel (q) frekansı kaça çıkmıştır?', '0,75', ['0,50', '0,25', '0,10'], '4 diploit kertenkelede toplam 8 alel vardır. 2 Yy bireyden 2 adet y, 2 yy bireyden 4 adet y olmak üzere toplam 6 adet y aleli bulunur; q = 6 / 8 = 0,75\'e fırlamıştır.'),
  ('Pasifik Okyanusu\'ndaki Pingelap mercan adasında 1775 yılındaki büyük tayfundan sonra hayatta kalan yaklaşık 20 kişiden birinin tam renk körlüğü (akromatopsi) taşıyıcısı olması ve sonraki kuşaklarda adalıların yaklaşık %10\'unun tam renk körü olması hangi olaylar zinciridir?', 'Doğal afet kaynaklı darboğaz etkisi ve ardından gelen küçük nüfus içi genetik sürüklenme', ['Tayfun sonrası güneş ışınlarının göz hücrelerinde yönlü mutasyonlar meydana getirmesi', 'Çevreye uyum sağlamak amacıyla adalıların karanlıkta görme genlerini geliştirmesi', 'Çevredeki diğer adalardan Pingelap adasına yoğun miktarda çekinik gen akışı olması'], 'Tayfun nüfusu 20 kişiye düşürerek klasik bir darboğaz (bottleneck) yaratmış, hayatta kalan tek taşıyıcının çok sayıda çocuğu olmasıyla çekinik alel yaygınlaşmıştır.'),
  ('Hardy-Weinberg koşullarından "popülasyonun çok büyük olması" şartı doğrudan hangi evrimsel mekanizmayı devre dışı bırakmak için gereklidir?', 'Genetik sürüklenmeyi', ['Nokta mutasyonlarını', 'Gen akışını', 'Rastgele döllenmeyi'], 'Popülasyon teorik olarak sonsuz (pratikte çok büyük) olduğunda örnekleme hatası sıfıra yaklaşır ve genetik sürüklenme alel frekanslarını değiştiremez.'),
  ('Dengedeki 10.000 kişilik bir kasabada otozomal çekinik bir özelliği fenotipinde gösteren 400 kişi yaşamaktadır. Kasabadan rastgele seçilen bir kişinin homozigot baskın genotipli olma olasılığı yüzde kaçtır?', '%64', ['%32', '%80', '%16'], 'q² = 400 / 10.000 = 0,04 olduğundan q = 0,2 ve p = 1 - 0,2 = 0,8 bulunur. Homozigot baskın olma olasılığı p² = (0,8)² = 0,64 yani %64\'tür.'),
  ('Aşağıdaki olaylardan hangisi bir popülasyonda "gen akışı" (gene flow) kapsamında değerlendirilir?', 'Rüzgarla taşınan çam polenlerinin elli kilometre uzaktaki başka bir çam ormanındaki kozalakları döllemesi', ['Aynı orman içindeki iki sincabın sonbaharda meşe palamudu saklamak için farklı ağaçlara tırmanması', 'Göçmen leyleklerin kışı geçirmek üzere Afrika\'ya uçup üremeden ilkbaharda kendi yuvalarına dönmesi', 'Bir bakteri hücresinin ikiye bölünerek kendisiyle aynı DNA\'ya sahip iki yeni yavru hücre oluşturması'], 'Gen akışı gerçekleşmesi için sadece fiziksel hareket yetmez; taşınan bireyin veya gametin (polen, spor vb.) hedef popülasyonda üreyerek genlerini aktarması gerekir.'),
  ('Bir adaya anakaradan yeni kurucu bireylerin ulaşması (kurucu etkisi) ile anakaradan adaya her yıl düzenli göç devam etmesi (sürekli gen akışı) adadaki popülasyonun anakaradan farklılaşmasını nasıl etkiler?', 'Tek seferlik kurucu olayı hızlı farklılaşma sağlarken, sürekli gen akışı farklılaşmayı engeller', ['Her iki durum da ada popülasyonunun anakarayla tamamen aynı kalmasına neden olur', 'Tek seferlik kurucu olayı çeşitliliği artırırken, sürekli gen akışı çeşitliliği sıfırlar', 'Sürekli gen akışı adada anında yeni bir tür oluştururken kurucu olayı evrimi durdurur'], 'İzolasyonla birleşen kurucu etkisi adanın gen havuzunu anakaradan hızla ayırır; ancak devam eden gen akışı iki havuzu sürekli eşitleyerek ayrışmayı önler.'),
  ('Dengedeki bir tavuk çiftliğinde ibik şeklini belirleyen gende gül ibik (R) aleli, balta ibik (r) aleline tam baskındır. Çiftlikteki 500 tavuğun 45 tanesi balta ibikli olduğuna göre, gül ibikli tavukların kaç tanesi heterozigottur?', '210', ['245', '455', '150'], 'q² = 45 / 500 = 0,09 ise q = 0,3 ve p = 0,7 bulunur. Heterozigot (Rr) oranı 2pq = 2 × 0,7 × 0,3 = 0,42\'dir; 500 × 0,42 = 210 tavuk heterozigot gül ibiklidir.'),
  ('Doğal seçilim olmadığı halde küçük bir ada popülasyonunda hafifçe zararlı bir alelin zamanla %100 sıklığa ulaşarak sabitlenmesi aşağıdakilerden hangisini kanıtlar?', 'Küçük popülasyonlarda genetik sürüklenmenin zayıf doğal seçilime üstün gelebildiğini', ['Zararlı alellerin küçük adalarda her zaman yararlı alellere dönüştüğünü', 'Doğal seçilimin ada ekosistemlerinde hiçbir canlı türü üzerinde çalışmadığını', 'Mutasyonların her nesilde yalnızca zararlı alel yönünde gerçekleştiğini'], 'Popülasyon çok küçük olduğunda şans dalgalanmaları (sürüklenme), zayıf seçilim baskısını bastırarak hafif zararlı alellerin bile sabitlenmesine yol açabilir.'),
  ('Galapagos Takımadaları\'na Güney Amerika anakarasından nadir fırtınalarla savrulan az sayıda ispinoz kuşunun farklı adalara yerleşip zamanla pek çok yeni türe ayrışmasında başlangıçtaki ilk genetik adım hangisidir?', 'Kurucu etkisiyle her adada ana popülasyondan farklı başlangıç gen havuzlarının oluşması', ['Adalara ulaşan kuşların ilk gün kendi istekleriyle gaga genlerini değiştirmesi', 'Anakaradaki tüm ispinozların aynı anda darboğaza girerek yok olması', 'Adalar arasında her gün kesintisiz ve çok yoğun gen akışının yaşanması'], 'Takımada türleşmelerinde (adaptif radyasyon) ilk adımı az sayıda öncünün yeni adaları kolonileştirdiği kurucu etkisi başlatır, ardından her adanın kendi ekolojisine göre doğal seçilim işler.'),
  ('Dengedeki bir güve popülasyonunda koyu kanat rengi aleli (K), açık kanat rengi aleline (k) baskındır. Popülasyondaki 2000 güvenin 1280 tanesi açık kanatlı olduğuna göre koyu kanatlı güvelerin kaç tanesi homozigot baskın (KK) genotiplidir?', '80', ['640', '720', '320'], 'Açık kanatlılar q² = 1280 / 2000 = 0,64 olduğundan q = 0,8 ve p = 0,2\'dir. Homozigot koyu (KK) oranı p² = 0,04 olup 2000 × 0,04 = 80 güve eder.'),
  ('Bir biyolog, nesli tehlikedeki bir orkide türünün kalan son 30 bireyini koruma altına almış ve dışarıdan hiçbir müdahale olmadan çiçeklerin rastgele tozlaşmasını sağlamıştır. Buna rağmen 5 kuşak sonra bazı nadir çiçek kokusu alellerinin yok olduğunu görmüştür. Bunun en olası açıklaması nedir?', 'Birey sayısı çok az (N = 30) olduğu için genetik sürüklenmeyle nadir alellerin şans eseri elenmesi', ['Rastgele tozlaşmanın doğası gereği her zaman nadir alelleri yok edip baskınları bırakması', 'Koruma altındaki bitkilerde mayoz bölünmenin hatalı gerçekleşerek kromozomları silmesi', 'Hardy-Weinberg dengesinin küçük popülasyonlarda sadece tek alele izin vermesi'], 'Seçilim, göç ve mutasyon olmasa bile N = 30 gibi çok küçük bir popülasyonda Hardy-Weinberg\'in "büyük nüfus" şartı sağlanamadığından genetik sürüklenme nadir alelleri kolayca siler.'),
  ('Bir popülasyonda kan grubu M olan 180 birey, MN olan 240 birey ve N olan 180 birey sayılmıştır. Bu popülasyonda M alelinin frekansı (p) kaçtır ve popülasyon dengede midir?', 'p = 0,5 olup popülasyon Hardy-Weinberg dengesinde değildir', ['p = 0,5 olup popülasyon Hardy-Weinberg dengesindedir', 'p = 0,3 olup popülasyon Hardy-Weinberg dengesinde değildir', 'p = 0,6 olup popülasyon Hardy-Weinberg dengesindedir'], 'Toplam 600 bireyde (1200 alel) M aleli sayısı = 2×180 + 240 = 600 olduğundan p = 0,5 ve q = 0,5\'tir. Dengede olsaydı MN sayısı 2×0,5×0,5×600 = 300 olmalıydı; 240 olduğu için dengede değildir.'),
  ('İnsan popülasyonlarında son yüzyıllarda kıtalar arası ulaşımın kolaylaşması ve farklı coğrafyalardan insanlar arasındaki evliliklerin artması, insan türünün küresel gen havuzunu nasıl etkilemektedir?', 'Popülasyonlar arası gen akışını artırarak bölgesel alel frekansı farklarını azaltmaktadır', ['Küresel ölçekte darboğaz etkisi yaratarak toplam gen çeşitliliğini düşürmektedir', 'Her ülkede ayrı kurucu etkileri başlatarak yeni insan türlerinin oluşmasını hızlandırmaktadır', 'Tüm çekinik alellerin bir kuşak içinde mutasyona uğrayarak kaybolmasını sağlamaktadır'], 'Küresel hareketlilik ve karışık evlilikler yoğun gen akışı (gene flow) yaratarak izole kalmış insan toplulukları arasındaki genetik farklılıkları azaltır ve heterozigotluğu artırır.'),
  ('Dengedeki bir fare popülasyonunda siyah kürk (S) kahverengi kürke (s) baskındır. Popülasyonda heterozigot siyah farelerin oranı %42 ve kahverengi farelerin oranı %49 olduğuna göre, homozigot siyah farelerin yüzdesi kaçtır?', '%9', ['%21', '%30', '%51'], 'Toplam genotip frekansları p² + 2pq + q² = %100\'dür. 2pq = %42 ve q² = %49 verildiğine göre p² = 100 - (42 + 49) = %9\'dur (q=0,7 ve p=0,3 ile de doğrulanır).'),
  ('Antibiyotiklerin bilinçsiz ve yarıda bırakılarak kullanılması sonucunda hastanelerde dirençli bakteri suşlarının hızla yaygınlaşması popülasyon genetiğindeki hangi temel ilkeyle açıklanır?', 'Yönlü doğal seçilimin duyarlı bakterileri eleyip direnç aleli taşıyanların frekansını artırmasıyla', ['Antibiyotik moleküllerinin bakteri ribozomlarına bağlanarak kurucu etkisi yaratmasıyla', 'Bakterilerin diploit yapıda olması nedeniyle çekinik direnç genlerini gizlemesiyle', 'İlaç kullanımının bakterilerde Hardy-Weinberg dengesini koruma altına almasıyla'], 'Antibiyotik güçlü bir seçici çevre baskısıdır; duyarlı bakteriler ölürken rastgele mutasyonla veya plazmitle direnç geni taşıyanlar hayatta kalıp hızla çoğalır.'),
  ('Sewall Wright tarafından geliştirilen "uyum coğrafyası" (adaptive landscape) modelinde genetik sürüklenmenin evrimsel rolü nasıl değerlendirilmiştir?', 'Küçük alt popülasyonların düşük uyumlu vadileri şansla aşarak daha yüksek uyum tepelerine geçmesini sağlaması', ['Tüm popülasyonları en derin uyum vadisine çekerek türlerin kesin olarak yok olmasına neden olması', 'Yalnızca milyonlarca bireylik dev popülasyonlarda mutasyon hızını sıfıra indirmesi', 'Doğal seçilimi tamamen ortadan kaldırarak tüm canlıları tek bir fenotipte birleştirmesi'], 'Wright\'ın "kayan denge" (shifting balance) kuramına göre, tek başına seçilim popülasyonu yerel bir tepede hapsederken sürüklenme vadileri aşmaya ve daha yüksek uyum zirvelerine ulaşmaya yardım edebilir.'),
  ('Dengedeki bir sincap popülasyonunda gür kuyruk (G) alelinin frekansı 0,8\'dir. Popülasyondaki 500 sincaptan kaç tanesinin fenotipik olarak gür kuyruklu olması beklenir?', '480', ['400', '320', '160'], 'p = 0,8 ise q = 0,2\'dir. Çekinik fenotip (gg) oranı q² = 0,04 olur. Gür kuyruklu (baskın fenotip: GG + Gg) oranı 1 - 0,04 = 0,96\'dır; 500 × 0,96 = 480 sincap gür kuyrukludur.'),
  ('Kuzey Amerika\'daki çayır tavuklarının (Tympanuchus cupido) tarım arazilerinin genişlemesiyle sayılarının Illinois eyaletinde binlerden 50\'nin altına düşmesi ve yumurtalarının açılma oranının %93\'ten %50\'nin altına gerilemesi hangi ardışık mekanizmaları gösterir?', 'Habitat kaybına bağlı darboğaz etkisi, genetik sürüklenme ve soy içi üreme depresyonu', ['Gen akışının artması, heterozigot üstünlüğü ve yönlü doğal seçilim başarısı', 'Rastgele eşleşmenin kurulması, Hardy-Weinberg dengesi ve biyotik potansiyel artışı', 'Kurucu etkisiyle yeni kıtaya yayılma ve zararlı alellerin tamamen temizlenmesi'], 'Klasik Illinois çayır tavuğu vakasında nüfus çöküşü (darboğaz) alel çeşitliliğini silmiş, akraba eşleşmeleriyle (soy içi üreme depresyonu) doğurganlık çökmüş; başka eyaletlerden kuş getirilerek (gen akışı/genetik kurtarma) popülasyon kurtarılmıştır.'),
  ('Dengedeki iki alelli bir bitki popülasyonunda çekinik fenotipli bireylerin oranı %25\'tir. Çevre koşullarının aniden değişmesiyle çekinik fenotipli bitkilerin tamamı çiçek açamadan kurumuştur. Kalan bitkilerin rastgele tozlaşmasıyla oluşacak bir sonraki nesilde çekinik alelin yeni frekansı (q₁) kaç olur?', '1 / 3', ['1 / 2', '1 / 4', '1 / 6'], 'Başlangıçta q² = 0,25 ise q₀ = 0,5 ve p₀ = 0,5\'tir (0,25 AA : 0,50 Aa : 0,25 aa). aa\'lar tamamen elendiğinde kalan 0,75\'lik grupta AA : Aa oranı 1 : 2\'dir (toplam 3 birim bireyde 6 alelin 2\'si a\'dır); ya da q₁ = q₀ / (1 + q₀) = 0,5 / 1,5 = 1/3 olur.'),
  ('Bir popülasyonda iki farklı alelin (örneğin A1 ve A2) frekanslarının ne sıfıra inip kaybolduğu ne de 1\'e ulaşıp sabitlendiği, aksine uzun nesiller boyunca belirli oranlarda bir arada korunduğu seçilim biçimlerinin genel adı nedir?', 'Dengeleyici seçilim (balancing selection)', ['Yönlü seçilim (directional selection)', 'Sabitleyici sürüklenme (fixation drift)', 'Kurucu darboğazı (founder bottleneck)'], 'Heterozigot avantajı ve negatif frekansa bağlı seçilim gibi polimorfizmi gen havuzunda aktif olarak koruyan süreçlerin çatı kavramı dengeleyici seçilimdir.'),
  ('Dengedeki bir popülasyonda çekinik alel frekansı q = 0,1 iken heterozigot bireylerin (2pq) homozigot çekinik bireylere (q²) sayısal oranı kaçtır?', '18', ['9', '2', '10'], 'p = 0,9 ve q = 0,1 olduğunda 2pq = 2 × 0,9 × 0,1 = 0,18 ve q² = (0,1)² = 0,01 olur. Oranları 0,18 / 0,01 = 18\'dir.'),
  ('Popülasyon genetiğinde "gen havuzu" kavramı değerlendirilirken üreme yaşını geride bırakmış kısır bireylerin taşıdığı alellerin gelecek nesil hesaplamalarına doğrudan katılmamasının nedeni nedir?', 'Gelecek kuşağın genotip oranlarını yalnızca fiilen gamet üreterek döllenmeye katılan bireylerin belirlemesi', ['Yaşlı bireylerin vücut hücrelerindeki tüm DNA moleküllerinin tamamen parçalanmış olması', 'Üreme sonrası bireylerde baskın alellerin kendiliğinden çekinik alellere dönüşmesi', 'Hardy-Weinberg denkleminin yalnızca embriyo dönemindeki canlılar için yazılmış olması'], 'Aktif gen havuzu bir sonraki kuşağa aktarılabilir genetik bilgiyi kapsar; üreme yetisi kalmayan bireylerin alelleri gelecek kuşağın gamet havuzuna giremez.'),
  ('Dengedeki 1600 bireylik bir böcek popülasyonunda homozigot baskın bireylerin sayısı 144\'tür. Bu popülasyonda çekinik fenotipli bireylerin sayısı kaçtır?', '784', ['672', '816', '1120'], 'Homozigot baskın oranı p² = 144 / 1600 = 0,09 olduğundan p = 0,3 ve q = 1 - 0,3 = 0,7 bulunur. Çekinik fenotipli (q²) birey sayısı = 1600 × (0,7)² = 1600 × 0,49 = 784\'tür.'),
  ('Tohum bankalarında ve hayvanat bahçelerindeki tür koruma programlarında bireylerin rastgele çiftleştirilmesi yerine soy kütüğü (pedigri) kayıtlarına bakılarak en uzak akrabaların birbiriyle eşleştirilmesinin popülasyon genetiğindeki temel gerekçesi nedir?', 'Küçük nüfusta genetik sürüklenmeyi ve homozigotlaşmayı yavaşlatarak mevcut alel çeşitliliğini maksimum korumak', ['Bireylerin hızlıca homozigot hale gelmesini sağlayarak çekinik hastalıkları ilk kuşakta ortaya çıkarmak', 'Popülasyondaki alel sayısını tek bir üstün alele indirgeyerek standart klon bireyler elde etmek', 'Hayvanat bahçesindeki canlıların vahşi doğadaki türdeşleriyle çiftleşme yeteneğini ortadan kaldırmak'], 'Çok küçük koruma popülasyonlarında rastgele eşleşme bile hızla akraba evliliğine ve alel kaybına yol açar; soy kütüğü bazlı yönetim etkili popülasyon büyüklüğünü (Ne) büyüterek gen havuzunu korur.'),
  ('İnsanlarda yeni doğan bebeklerin doğum ağırlığının çok düşük veya çok yüksek olması ölüm riskini artırırken, ortalama ağırlıktaki (yaklaşık 3-3,5 kg) bebeklerin hayatta kalma oranının en yüksek olması hangi seçilim mekanizmasıyla açıklanır?', 'Dengeleyici seçilim', ['Yönlü seçilim', 'Dallandırıcı seçilim', 'Eşeysel seçilim'], 'Uç fenotiplerin elenip ortalama fenotipe sahip bireylerin avantaj sağladığı seçilim biçimi dengeleyici seçilimdir.'),
  ('Bir böcek popülasyonuna aynı tarım ilacı yıllar boyunca düzenli olarak uygulandığında ilaçtan etkilenmeyen bireylerin oranının %2\'den %85\'e çıkması sürecinde gerçekleşen olay nedir?', 'İlaç dirençli alellere sahip bireylerin seçilerek üreme başarısının artması', ['İlacın böceklerin üreme ana hücrelerinde yalnızca yararlı mutasyonları tetiklemesi', 'Dirençsiz bireylerin yaşamları boyunca kazandıkları bağışıklığı yavrularına aktarması', 'Popülasyondaki tüm bireylerin genotiplerinin aynı anda ilaca uyumlu hale gelmesi'], 'Tarım ilacı seçici bir baskı oluşturarak dirençsiz böcekleri eler; dirençli genotipe sahip olanlar hayatta kalıp çoğalarak popülasyondaki frekanslarını artırır.'),
  ('Aşağıdaki olaylardan hangisi eşeyli üreyen bir bitki popülasyonunda kalıtsal varyasyonun artmasına doğrudan katkı sağlamaz?', 'Tohumların çimlenme sürecinde mitoz bölünmeyle kök hücrelerinin çoğalması', ['Mayoz bölünmenin profaz I evresinde homolog kromozomlar arasında parça değişimi', 'Metafaz I evresinde homolog kromozomların ekvatoral düzlemde rastgele dizilmesi', 'Yumurta hücresinin genetik yapısı farklı polen çekirdeklerinden biriyle döllenmesi'], 'Mitoz bölünme (mutasyon olmadığı sürece) genetik yapıyı aynen koruduğu için kalıtsal çeşitlilik yaratmaz; mayoz ve döllenme ise varyasyonu artırır.'),
  ('Orak hücreli anemi aleli bakımından heterozigot (HbA HbS) bireylerin sıtma hastalığının yaygın olduğu Afrika bölgelerinde hem sağlam homozigotlara (HbA HbA) hem de orak hücre hastalarına (HbS HbS) göre daha yüksek hayatta kalma şansına sahip olması neyi kanıtlar?', 'Heterozigot üstünlüğünün zararlı bir çekinik aleli popülasyonda koruduğunu', ['Yönlü seçilimin sıtma bölgelerinde normal hemoglobin alelini tamamen yok ettiğini', 'Sıtma parazitinin insan alyuvarlarında oraklaşma mutasyonunu doğrudan başlattığını', 'Dallandırıcı seçilimin popülasyonu iki ayrı üreme grubuna hızla ayırdığını'], 'Heterozigot avantajı dengeleyici bir seçilim mekanizması olarak işler ve homozigot durumda ölümcül olabilen HbS alelinin popülasyondan elenmesini önler.'),
  ('Kuraklığın uzun sürdüğü bir adada küçük ve yumuşak tohumların tükenip yalnızca büyük ve sert kabuklu tohumların kalması üzerine, adadaki ispinoz kuşlarının ortalama gaga derinliğinin birkaç kuşak içinde artması hangi seçilim türüdür?', 'Yönlü seçilim', ['Dengeleyici seçilim', 'Dallandırıcı seçilim', 'Eşeysel seçilim'], 'Besin kaynağının tek bir uca (büyük ve sert tohumlar) kayması, daha kalın ve derin gagalı kuşlara seçilim avantajı sağlayarak ortalamayı o yöne kaydırır.'),
  ('Aşağıdakilerden hangisi bir popülasyonda dengeleyici doğal seçilimin uzun süre etkili olduğunun en güçlü göstergesidir?', 'Fenotipik varyasyon aralığının daralması ve ortalama değere sahip bireylerin oranının artması', ['Popülasyonun fenotip dağılım grafiğinin ortasının çökerek çift tepeli bir eğriye dönüşmesi', 'Ortalama fenotip değerinin kuşaklar boyunca sürekli olarak tek bir uç değere doğru kayması', 'Popülasyondaki çekinik alellerin tamamının birkaç kuşak içinde hızlıca yüzde yüze ulaşması'], 'Dengeleyici seçilim her iki uçtaki bireyleri elediği için genetik ve fenotipik dağılımı daraltır, çan eğrisini ortada sivrileştirir.'),
  ('Sanayi Devrimi sonrasında İngiltere\'de çevre kirliliği yasalarının çıkarılması ve fabrika bacalarına filtre takılmasıyla ağaç gövdelerindeki likenlerin yeniden gelişmesi, biberli güve popülasyonunu nasıl etkilemiştir?', 'Açık renkli güvelerin kamuflaj avantajı yeniden arttığı için yönlü seçilim yön değiştirerek açık renk frekansını yükseltmiştir', ['Koyu renkli güveler baskın alel taşıdığı için çevre temizlense bile popülasyondaki oranları artmaya devam etmiştir', 'Hem açık hem koyu renkli güveler elenmiş ve yalnızca gri benekli ara formlar dengeleyici seçilimle hayatta kalmıştır', 'Koyu renkli güveler likenlerle beslenemediği için açlıktan topluca yok olarak türün nesli tamamen tükenmiştir'], 'Doğal seçilimin yönü çevre koşullarına bağlıdır; ağaçlar tekrar açık renkli likenlerle kaplanınca kuş avcılığı koyu güveleri elemiş ve açık renkliler yeniden çoğalmıştır.'),
  ('Aynı kromozom üzerinde bulunan bağlı genlerin mayoz bölünme sırasında birbirinden ayrılarak yeni alel kombinasyonları oluşturmasını sağlayan olay hangisidir?', 'Krossing over', ['Nokta mutasyonu', 'Kromozom ayrılmaması', 'Sitoplazma bölünmesi'], 'Bağlı genler ancak profaz I evresinde kardeş olmayan kromatitler arasındaki parça değişimi (krossing over) ile ayrılarak rekombinasyon oluşturabilir.'),
  ('Fosil kayıtlarında yüz milyonlarca yıldır dış morfolojisinde çok az değişim gözlenen at nalı yengeci ve Latimeria (sölakant) gibi "yaşayan fosil" türlerin varlığı hangi seçilim biçiminin etkisiyle en iyi açıklanır?', 'Dengeleyici seçilim', ['Dallandırıcı seçilim', 'Yönlü seçilim', 'Yapay seçilim'], 'Yaşam alanlarındaki ekolojik koşulların çok uzun süre kararlı kalması durumunda dengeleyici seçilim uç sapmaları eler ve mevcut başarılı formu korur.'),
  ('Bir tarladaki yabani otları yok etmek için herbisit (ot ilacı) kullanan bir çiftçi, beş yıl sonra aynı ilacın dozunu iki katına çıkarmasına rağmen otların kurumadığını fark etmiştir. Bu süreçte herbisitin üstlendiği rol nedir?', 'Popülasyondaki herbisite duyarlı ve dirençli bireyleri birbirinden ayıran seçici çevre faktörü olmak', ['Yabani otların kloroplast DNA\'sında fotosentezi hızlandıran özel direnç genlerini sentezlemek', 'Topraktaki yararlı mineralleri bağlayarak otların eşeysiz üremesini eşeyli üremeye dönüştürmek', 'Bitki köklerinde modifikasyon meydana getirerek ilacın hücre içine girişini geçici olarak engellemek'], 'Kimyasal ilaçlar direnç mutasyonu yaratmaz; var olan genetik çeşitlilik içinde duyarlıları öldürüp dirençlilerin hayatta kalmasını sağlayan seçici baskı unsurudur.'),
  ('Küresel iklim değişikliği nedeniyle kar yağışının azaldığı kuzey ormanlarında, kışın kahverengi kalan alaca baykuşların (Strix aluco) beyaz tüylü olanlara göre son on yılda oransal olarak artması neyi gösterir?', 'Karsız ortamda kahverengi tüylü baykuşların daha iyi gizlenerek yönlü seçilimle avantaj sağladığını', ['Beyaz tüylü baykuşların havaların ısınmasıyla tüylerindeki beyaz pigmentleri kahverengiye dönüştürdüğünü', 'Baykuş popülasyonunda dallandırıcı seçilimle iki farklı coğrafi alttürün aynı ormanda oluştuğunu', 'Tüy renginin kalıtsal olmadığını ve yalnızca kış mevsimindeki hava sıcaklığına bağlı geliştiğini'], 'Kar örtüsü azaldığında beyaz tüylü bireyler belirginleşip dezavantajlı duruma düşerken, kahverengi kalıtsal varyant yönlü seçilimle yaygınlaşmıştır.'),
  ('Bakterilerin içinde bulundukları dış ortamda serbest halde bulunan yabancı DNA parçalarını hücre içine alarak kendi genomlarına katmalarıyla çeşitlilik kazanmasına ne ad verilir?', 'Transformasyon', ['Transdüksiyon', 'Konjugasyon', 'Translasyon'], 'Bakterinin çevredeki çıplak DNA moleküllerini hücre zarından içeri alıp genetik yapısına dahil etmesi transformasyon olarak adlandırılır.'),
  ('Hastanelerin yoğun bakım ünitelerinde "süper bakteri" olarak adlandırılan çoklu ilaca dirençli bakterilerin (örneğin MRSA) evsel ortamlara göre çok daha sık ortaya çıkmasının temel nedeni nedir?', 'Yoğun ve sürekli antibiyotik kullanımının çok güçlü bir yönlü seçilim baskısı oluşturması', ['Hastane ortamındaki tıbbi cihazlardan yayılan ışınların bakterileri doğrudan süper türe dönüştürmesi', 'Evsel ortamlarda yaşayan bakterilerin hücre duvarlarında peptidoglikan tabakasının hiç bulunmaması', 'Yoğun bakım hastalarının kanındaki antikorların bakterilere direnç genlerini yatay gen transferiyle vermesi'], 'Antibiyotiklerin en yoğun kullanıldığı yerler hastaneler olduğundan, dirençsiz tüm rakipler elenir ve dirençli suşlar rekabetsiz ortamda hızla baskın hale gelir.'),
  ('Evrimsel biyolojide "uyum başarısı" (evrimsel fitness) kavramı bir bireyin hangi özelliğini ifade eder?', 'Hayatta kalarak bir sonraki kuşağa aktarabileceği doğurgan yavru bırakma başarısını', ['Popülasyondaki diğer tüm bireylerden fiziksel olarak daha iri ve kaslı olmasını', 'Hiçbir bulaşıcı hastalığa yakalanmadan türünün en uzun ömürlü bireyi olmasını', 'Bulunduğu ekosistemdeki tüm besin zincirlerinin en üst basamağında yer almasını'], 'Bir canlı ne kadar güçlü veya uzun ömürlü olursa olsun, üreyip genlerini doğurgan yavrularla sonraki kuşağa aktaramıyorsa evrimsel uyum başarısı (fitness) sıfırdır.'),
  ('Kuzey Kutbu\'na yakın tundralarda yaşayan kar tavşanlarının kışın beyaz kürklü olanlarının vaşaklar tarafından daha az avlanması, ancak küresel ısınmayla karın erken eridiği bahar aylarında açık hedef haline gelmesi neyi kanıtlar?', 'Bir adaptasyonun avantajlı olup olmadığının içinde bulunulan çevre koşullarına göre değişebildiğini', ['Doğal seçilimin her zaman beyaz kürklü bireyleri kahverengi kürklü bireylere karşı koruduğunu', 'Vaşakların avlanma tercihlerinin tavşan popülasyonunun gen frekansları üzerinde hiçbir etkisi olmadığını', 'Tavşanların kürk rengini yırtıcıyı gördükleri anda bukalemun gibi saniyeler içinde değiştirebildiğini'], 'Doğal seçilimde mutlak iyi bir özellik yoktur; kar varken koruyucu olan beyaz kürk, kar erken eridiğinde kamuflajı bozarak dezavantaja dönüşür.'),
  ('Çöl kertenkelelerinin bazılarının siyah bazılarının açık sarı derili olduğu bir bölgede, yalnız bazalt (siyah volkanik kaya) zemin üzerinde yaşayan popülasyonda birkaç on yıl içinde siyah kertenkele oranının %95\'e ulaşması nasıl gerçekleşmiştir?', 'Açık sarı bireylerin siyah kayalar üzerinde yırtıcı kuşlarca kolayca fark edilip avlanarak elenmesiyle', ['Siyah bazalt kayalardan yayılan ısının sarı kertenkelelerin derisinde kalıtsal melanin genini yaratmasıyla', 'Sarı kertenkelelerin siyah kayalar üzerinde güneşlenirken derilerinin kalıcı olarak yanıp kararmasıyla', 'Dengeleyici seçilimin hem siyah hem sarı bireyleri koruyarak alacalı bireyleri yok etmesiyle'], 'Bazalt zemin üzerinde açık renkli bireyler görsel avcılar tarafından seçilip avlanırken, koyu renkli bireyler gizlenerek hayatta kalmış ve yönlü seçilimle çoğalmıştır.'),
  ('Bir araştırmacı özdeş genetik yapıya (klon) sahip yüz adet su piresini (Daphnia) tuzluluk oranı kademeli olarak artırılan bir akvaryuma koyduğunda, belirli bir eşikten sonra tüm bireylerin öldüğünü ve dirençli bir grubun çıkmadığını görmüştür. Bunun temel nedeni nedir?', 'Başlangıçtaki klon popülasyonunda doğal seçilimin işleyebileceği kalıtsal varyasyonun bulunmaması', ['Su pirelerinin yalnızca tatlı sularda eşeyli, tuzlu sularda ise eşeysiz üreyebilme özelliğine sahip olması', 'Tuzlu suyun canlı hücrelerde hiçbir koşulda mutasyona veya fizyolojik strese izin vermemesi', 'Dengeleyici seçilimin tuzluluk artışına karşı tüm bireyleri aynı anda koruma altına alamaması'], 'Klon popülasyonunda genetik varyasyon (yeni mutasyon yoksa) sıfırdır; dolayısıyla seçici baskı uygulandığında avantajlı alel taşıyan birey bulunmadığından tamamı elenir.'),
  ('Malthus\'un "popülasyonlar geometrik diziyle artma eğilimindeyken besin kaynakları aritmetik diziyle artar" görüşü Darwin\'in kuramında hangi temel çıkarıma esin kaynağı olmuştur?', 'Kaynakların sınırlı olması nedeniyle doğada bireyler arasında kaçınılmaz bir yaşam mücadelesi yaşandığına', ['Canlıların besin kıtlığı çektiğinde fotosentez yapabilmek için kloroplast genleri edindiğine', 'Tüm türlerin birey sayısının doğada hiçbir zaman değişmeden sonsuza dek sabit kaldığına', 'Doğal seçilimin yalnız bol besin bulunan yıllarda devreye girip kıtlıkta tamamen durduğuna'], 'Üretilen yavru sayısının ortamın taşıma kapasitesinden fazla olması, bireyler arasında sınırlı kaynaklar için rekabet (yaşam mücadelesi) doğurur.'),
  ('Darwin\'in görüşüne göre zürafaların uzun boyunlu olmasının evrimsel açıklaması aşağıdakilerden hangisidir?', 'Atasal popülasyonda kalıtsal olarak daha uzun boyunlu doğan bireylerin kurak dönemlerde yüksek yapraklara ulaşıp hayatta kalarak çoğalması', ['Kısa boyunlu zürafaların boyun omurlarını sürekli gerdirerek DNA dizilimlerini uzun boyun oluşturacak biçimde değiştirmesi', 'Dişi zürafaların yalnızca kısa boyunlu erkeklerle çiftleşmeyi reddetmesi sonucu tüm otçul memelilerin boynunun uzaması', 'İnsanların binlerce yıl önce binek hayvanı olarak kullanmak amacıyla en uzun boyunlu zürafaları seçip üretmesi'], 'Darwinci açıklamada popülasyonda boyun uzunluğu bakımından kalıtsal varyasyon zaten vardır; besin kıtlığında uzun boyunlular avantaj sağlayıp seçilmiştir.'),
  ('Aşağıdaki mutasyon çeşitlerinden hangisinin sentezlenecek polipeptit zincirinin amino asit diziliminde en geniş çaplı bozulmaya (çerçeve kaymasına) yol açması beklenir?', 'Genin başlangıç kısmına yakın bir bölgeden tek bir nükleotidin eksilmesi', ['Genin son kodonundan hemen önceki kodonda eş anlamlı baz değişimi olması', 'Kodlama yapmayan intron bölgesinde bir adenin yerine guanin nükleotidi gelmesi', 'Üçlü bir kodonun tamamının (3 ardışık nükleotidin) diziden birlikte çıkması'], 'Tek bir nükleotidin eklenmesi veya silinmesi okuma çerçevesini (reading frame) o noktadan itibaren tamamen kaydırarak sonraki tüm amino asitleri değiştirir.'),
  ('Tek yumurta ikizi olan iki bireyden birinin deniz seviyesinde, diğerinin ise yüksek rakımlı bir dağ köyünde yaşaması sonucunda dağda yaşayanın kanındaki alyuvar sayısının daha yüksek çıkması hangi kavramla açıklanır ve evrimsel değeri nedir?', 'Modifikasyondur; gen dizilimini değiştirmediği için doğal seçilimle gelecek kuşaklara aktarılmaz', ['Adaptasyondur; yüksek rakıma uyum sağlayan bireyin çocukları da deniz seviyesinde yüksek alyuvarla doğar', 'Yönlü seçilimdir; dağ köyünde yaşayan ikizin kan grubu alelleri düşük oksijene göre kalıcı değişmiştir', 'Nokta mutasyonudur; güneşten gelen morötesi ışınlar kemik iliği kök hücrelerinin kromozom sayısını artırmıştır'], 'Yüksek rakımda alyuvar artışı fizyolojik bir uyum (modifikasyon/aklimatizasyon) olup kalıtsal değildir; kişi deniz seviyesine inince sayı normale döner.'),
  ('Bir bakteri popülasyonunda streptomisin antibiyotiğine dirençli mutantların varlığını kanıtlamak için Joshua ve Esther Lederberg tarafından yapılan "kopya ekim" (replika plaklama) deneyinde ulaşılan temel sonuç nedir?', 'Dirençli bakterilerin antibiyotikle hiç karşılaşmadan önce de ana kültürde rastgele mutasyonla var olduğu', ['Antibiyotikli besi yerine temas eden her bakterinin birkaç dakika içinde direnç genini sıfırdan ürettiği', 'Kadife kumaşla taşınan bakterilerin yalnızca karanlık ortamda streptomisine karşı bağışıklık kazandığı', 'Bakterilerde kalıtsal özelliklerin DNA yerine hücre duvarındaki yağ molekülleriyle yavrulara aktarıldığı'], 'Kopya ekim deneyi, hiç antibiyotik görmemiş ana kaptaki belirli kolonilerin zaten dirençli olduğunu göstererek mutasyonların seçici etkenden önce ve rastgele oluştuğunu kanıtlamıştır.'),
  ('Mayoz bölünmenin anafaz I evresinde anne ve babadan gelen homolog kromozomların hücrenin zıt kutuplarına rastgele çekilmesi evrimsel açıdan neden önemlidir?', 'Gametlerde çok sayıda farklı kromozom kombinasyonu oluşturarak kalıtsal varyasyonu artırdığı için', ['Kromozomlardaki hasarlı genleri onararak popülasyondaki mutasyon oranını sıfıra indirdiği için', 'Türün kromozom sayısını her kuşakta iki katına çıkararak poliploid bireyler ürettiği için', 'Yalnızca baskın alellerin yumurta ve sperm hücrelerine geçmesine izin verdiği için'], 'İnsanda 2^23 farklı kromozom kombinasyonlu gamet oluşmasını sağlayan bu bağımsız dağılım olayı, eşeyli üremedeki kalıtsal varyasyonun ana kaynaklarındandır.'),
  ('Kuzey Amerika\'da yaşayan cep farelerinin açık renkli kumullarda yaşayanlarının açık kürk rengine, birkaç kilometre ötedeki koyu renkli lav kayalıklarında yaşayanlarının ise koyu kürk rengine sahip olduğu, ancak iki bölgedeki farelerin beslenme ve sıcaklık koşullarının aynı olduğu saptanmıştır. Bu farklılığın temel seçici nedeni nedir?', 'Gece avlanan baykuş ve şahin gibi görsel avcıların zemine uymayan fareleri seçerek avlaması', ['Lav kayalıklarındaki demir ve magnezyum minerallerinin farelerin kürkünü siyaha boyaması', 'Kumullarda yaşayan farelerin kum tanelerini yutarak melanin sentezini kalıcı olarak durdurması', 'Koyu renkli farelerin açık renkli farelere göre soğuğa karşı her zaman daha dayanıksız olması'], 'İklim ve besin aynıyken yalnız zemin renginin değiştiği bu klasik örnekte (Chaetodipus intermedius), görsel yırtıcılardan korunma (kamuflaj) kürk rengini belirleyen seçilim baskısıdır.'),
  ('Bir popülasyonda yönlü doğal seçilim uzun kuşaklar boyunca aynı yönde devam ederse gen havuzunda nasıl bir değişim beklenir?', 'Avantaj sağlayan alelin frekansı artarken dezavantajlı alelin frekansı kademeli olarak azalır', ['Popülasyondaki tüm alellerin frekansı birbirine eşitlenerek genetik denge korunur', 'Yalnızca heterozigot bireyler hayatta kalır ve homozigot bireylerin tamamı elenir', 'Mutasyon hızı sıfırlanarak popülasyonda yeni varyasyonların oluşumu tamamen durur'], 'Yönlü seçilim belirli bir fenotipi ve onun altında yatan alelleri kayırdığından, avantajlı alelin sıklığı gen havuzunda yükselir.'),
  ('Çekirge popülasyonlarında yeşil çayırlarda yeşil bireylerin, kurak bozkırlarda ise sarı-kahverengi bireylerin baskın olması; ancak mevsim normallerinin dışında aşırı kurak geçen bir yılda yeşil çayırlardaki sarı-kahverengi çekirge oranının hızla yükselmesi neyi gösterir?', 'Çevresel değişimlerin doğal seçilimin yönünü ve avantajlı fenotipi kısa sürede değiştirebildiğini', ['Yeşil çekirgelerin kuraklık başladığında klorofil pigmentlerini kaybederek sarardığını', 'Doğal seçilimin yalnız kurak yıllarda işlediğini, yağışlı yıllarda ise tamamen durduğunu', 'Çekirgelerde vücut renginin genlerle hiçbir ilgisi olmayıp yenen otun renginden kaynaklandığını'], 'Çayırlar kuruyup sarardığında önceden dezavantajlı olan sarı-kahverengi kalıtsal varyantlar gizlenme avantajı elde eder ve yönlü seçilimle oranları artar.'),
  ('İnsanlarda apandisit veya yirmi yaş dişleri gibi körelmiş (vestigial) yapıların varlığı doğal seçilim açısından nasıl yorumlanır?', 'Atasal türlerde işlevsel olan bu yapıların, beslenme ve yaşam biçimi değiştikçe eski seçilim baskısını yitirerek küçülmüş kalıntılar olduğu', ['İnsan türünde gelecekte yeni besinleri sindirmek amacıyla şimdiden sıfırdan evrimleşmekte olan taslak organlar olduğu', 'Embriyonik gelişim sırasında radyasyona maruz kalan bireylerde sonradan ortaya çıkan zararlı somatik mutasyonlar olduğu', 'Dengeleyici seçilimin insan vücudundaki tüm organları eksiksiz ve maksimum büyüklükte tutmak için koruduğu yapılar olduğu'], 'Otçul ağırlıklı beslenen atalarda selüloz sindirimi ve öğütme için kritik olan yapılar, diyetin değişmesiyle avantaj olmaktan çıkmış, hatta enfeksiyon riski nedeniyle küçülme yönünde seçilmiştir.'),
  ('Panama Kıstağı\'nın yükselmesiyle Atlas Okyanusu ve Büyük Okyanus\'ta birbirinden ayrılan karides popülasyonlarının zamanla birbirleriyle çiftleşemeyen ayrı türlere dönüşmesi hangi süreci kanıtlar?', 'Allopatrik türleşmeyi', ['Simpatrik türleşmeyi', 'Yakınsak evrimi', 'Yapay seçilimi'], 'Kara köprüsünün oluşumu deniz canlıları için aşılması imkânsız bir coğrafi engel yaratmış, gen akışı kesilen karides popülasyonları allopatrik olarak türleşmiştir.'),
  ('Aynı gölde yaşayan iki balık popülasyonundan birinin yalnızca gölün sığ kıyı sularında, diğerinin ise yalnızca derin dip sularında beslenip üremesi hangi zigot öncesi engeli gösterir?', 'Habitat (ekolojik) yalıtımı', ['Mevsimsel (zamansal) yalıtımı', 'Gametik yalıtımı', 'Melez kısırlığı engelini'], 'Aynı coğrafi bölgede bulunmalarına rağmen farklı mikro yaşam alanlarını (nişleri) tercih ettikleri için karşılaşmayan türler arasında habitat (ekolojik) yalıtımı vardır.'),
  ('İki farklı salyangoz türünün kabuk sarmal yönlerinin (sağa veya sola dönük) zıt olması nedeniyle üreme açıklıklarının yan yana gelememesi hangi yalıtım türüdür?', 'Mekanik yalıtım', ['Davranışsal yalıtım', 'Gametik yalıtım', 'Zamansal yalıtım'], 'Üreme organlarının anatomik veya morfolojik uyumsuzluğu nedeniyle çiftleşmenin fiziksel olarak gerçekleşememesine mekanik yalıtım adı verilir.'),
  ('Suya yumurta ve sperm bırakan denizkestanesi türlerinin gametleri su ortamında karşılaşsa bile farklı türlerin hücre zarındaki reseptörlerin uyuşmaması sonucu döllenmenin olmaması nedir?', 'Gametik yalıtım', ['Mekanik yalıtım', 'Habitat yalıtımı', 'Melez bozulması'], 'Erkek ve dişi üreme hücrelerinin (gametlerin) kimyasal veya moleküler uyumsuzluk nedeniyle kaynaşamaması durumuna gametik yalıtım denir.'),
  ('İki farklı semender türü doğada çiftleşip döllenmiş yumurta oluşturabilmesine rağmen gelişen embriyoların büyük çoğunluğunun yumurtadan çıkamadan ölmesi hangi üreme engelidir?', 'Melez yaşayamazlığı', ['Gametik yalıtım', 'Melez bozulması', 'Mekanik yalıtım'], 'Zigot oluştuktan sonra genetik uyumsuzluk nedeniyle embriyonik gelişimin tamamlanamaması veya bireyin erginleşmeden ölmesi melez yaşayamazlığıdır.'),
  ('İki farklı pamuk türünün çaprazlanmasıyla elde edilen birinci kuşak (F1) melezlerin sağlıklı ve doğurgan olmasına karşın, bunların kendi aralarında üremesiyle oluşan ikinci kuşak (F2) bireylerin cılız ve kısır çıkması nasıl adlandırılır?', 'Melez bozulması', ['Melez yaşayamazlığı', 'Gametik uyumsuzluk', 'Davranışsal yalıtım'], 'F1 kuşağı verimli iken F2 veya sonraki kuşaklarda zayıflık ve kısırlık ortaya çıkması zigot sonrası engellerden melez bozulması (melez çöküşü) olarak tanımlanır.'),
  ('Tek bir türe ait bireylerde mayoz bölünme hatası sonucu kromozomların ayrılmamasıyla 2n\'den doğrudan 4n kromozomlu yeni bir bitki türünün oluşmasına ne ad verilir?', 'Otopoliploidi', ['Allopoliploidi', 'Aneuploidi', 'Yarı korunumlu eşlenme'], 'Başka bir türle melezleşme olmaksızın, tek bir ata türün kendi kromozom takımının katlanmasıyla gerçekleşen poliploidi biçimine otopoliploidi denir.'),
  ('Kuzey Amerika\'da yaşayan elma kurtçuklarının bir kısmının, kıtaya sonradan getirilen elma ağaçlarına uyum sağlayıp atalarının yaşadığı alıç ağaçlarındaki popülasyondan farklı zamanda üremeye başlaması neyin kanıtıdır?', 'Devam etmekte olan simpatrik türleşmenin', ['Buzul çağı kaynaklı allopatrik türleşmenin', 'Zigot sonrası melez yaşayamazlığının', 'Kıtalararası yapay klonlama sürecinin'], 'Aynı coğrafi bölgede fiziksel bariyer olmadan konak bitki tercihi ve meyve olgunlaşma zamanı farkıyla gen akışının azalması simpatrik türleşmenin klasik bir örneğidir.'),
  ('Victoria Gölü\'ndeki çiklit (cichlid) balıklarında dişilerin, suyun derinliğine göre değişen ışık rengi altında erkeklerin parlak pullarını seçerek eşleşmesi hangi türleşme ve yalıtım ikilisine örnektir?', 'Simpatrik türleşme ve davranışsal yalıtım', ['Allopatrik türleşme ve mekanik yalıtım', 'Allopatrik türleşme ve melez kısırlığı', 'Simpatrik türleşme ve melez yaşayamazlığı'], 'Aynı gölde coğrafi engel olmaksızın eşeysel seçilim ve eş tanıma davranışlarıyla gen akışının kesilmesi, davranışsal yalıtım aracılığıyla gerçekleşen simpatrik türleşmedir.'),
  ('Büyük Kanyon\'un iki yakasında yaşayan iki sincap popülasyonunun kanyon oluşmadan önce tek bir tür olduğu bilinmektedir. Bu süreçte ilk ortaya çıkan olay aşağıdakilerden hangisidir?', 'Coğrafi yalıtımla popülasyonlar arasındaki gen akışının kesilmesi', ['İki popülasyon arasında eşzamanlı poliploidi mutasyonunun görülmesi', 'Sincapların beslenme şeklinin etçil diyete doğru aniden değişmesi', 'Aynı yuvada yaşayan bireylerin kur yapma seslerinin farklılaşması'], 'Allopatrik türleşmede başlangıç adımı fiziksel engelin (kanyonun) ortaya çıkarak popülasyonlar arasındaki gen akışını durdurmasıdır; genetik farklılaşma ve üreme yalıtımı bundan sonra birikir.'),
  ('Ada çiçeklerinin taç yaprak borusu uzunluğunun sadece belirli bir arı türünün hortumuna uygun olması, diğer çiçekteki polenlerin ise yalnızca sineklerin sırtına yapışacak yapıda olması çiçekler arasında hangi yalıtımı sağlar?', 'Mekanik yalıtım', ['Mevsimsel yalıtım', 'Melez kısırlığı', 'Melez bozulması'], 'Çiçekli bitkilerde tozlaştırıcı hayvanın vücut yapısına göre özelleşmiş çiçek morfolojisi, polenin yanlış türe taşınmasını fiziksel olarak önlediği için mekanik yalıtım kapsamında değerlendirilir.'),
  ('Aslan (Panthera leo) ile kaplanın (Panthera tigris) doğal yaşam alanları büyük ölçüde ayrı olduğundan doğada çiftleşmezler; ancak hayvanat bahçesinde aynı kafese konulduklarında çiftleşip "liger" adı verilen yavrular doğurabilirler. Doğadaki bu ayrım öncelikle hangi engele dayanır?', 'Ekolojik ve coğrafi yalıtım', ['Gametik uyumsuzluk', 'Mekanik yalıtım', 'Zigot yaşayamazlığı'], 'Hayvanat bahçesinde yavru oluşabilmesi mekanik ve gametik engelin tam olmadığını, doğada melezlenmemelerinin ise coğrafi/habitat ayrılığından kaynaklandığını gösterir.'),
  ('Ana karadaki büyük bir kuş popülasyonundan fırtınayla kopan birkaç bireyin ıssız bir okyanus adasına ulaşıp orada yeni ve farklı bir türe evrimleşmesi olayında başlangıçta etkili olan mekanizma hangisidir?', 'Kurucu etkisi ve allopatrik yalıtım', ['Simpatrik poliploidi ve yapay seçilim', 'Gen akışı artışı ve melez bozulması', 'Dengeleyici seçilim ve gametik birleşme'], 'Büyük popülasyondan küçük bir grubun ayrılarak yeni bir coğrafi alanı kolonileştirmesi kurucu etkisine (genetik sürüklenme) ve allopatrik türleşmeye yol açar.'),
  ('Çiftçilerin modern ekmeklik buğdayı (Triticum aestivum, 2n=6x=42) elde etme sürecinde yabani ot türleriyle kültür buğdaylarının melezlenip kromozom sayılarının katlanması hangi evrimsel mekanizmanın sonucudur?', 'Allopoliploidi yoluyla türleşme', ['Yalnızca coğrafi engelle allopatrik türleşme', 'Mevsimsel yalıtımla gen havuzu daralması', 'Körelmiş organların yeniden aktifleşmesi'], 'Ekmeklik buğday, üç farklı diploit ata türün (AA, BB, DD genomları; her biri 2n=14) ardışık melezlenmesi ve kromozom katlanmasıyla (allopoliploidi) oluşmuş hekzaploit (6n=42) bir türdür.'),
  ('Memelilerde dişi üreme kanalının kimyasal ortamının, farklı bir türden gelen spermleri antijenik olarak tanıyıp hareketsiz bırakması veya yok etmesi hangi yalıtım basamağında değerlendirilir?', 'Gametik yalıtım', ['Davranışsal yalıtım', 'Melez yaşayamazlığı', 'Melez kısırlığı'], 'Çiftleşme gerçekleşmiş olsa bile henüz döllenme (zigot oluşumu) meydana gelmeden spermin yumurtaya ulaşmasının veya kaynaşmasının önlenmesi zigot öncesi gametik yalıtımdır.'),
  ('Bir botanikçi aynı çayırda yetişen iki orkide türünün polenlerini laboratuvarda yapay olarak birbirinin dişicik tepesine sürdüğünde sağlıklı ve verimli tohumlar elde edebiliyor; ancak doğada bu iki tür hiç melezlenmiyorsa, doğadaki engel hangisi OLABİLİR?', 'Çiçek açma mevsimlerinin veya tozlaştırıcı böceklerinin farklı olması', ['Tohum taslağındaki yumurta ile polen çekirdeğinin genetik uyuşmazlığı', 'Oluşan embriyonun çimlenme aşamasında genetik olarak ölmesi', 'Birinci kuşak melez bitkilerin mayoz bölünme geçirememesi'], 'Yapay tozlaşmada verimli tohum elde edilmesi gametik ve tüm zigot sonrası engellerin olmadığını kanıtlar; dolayısıyla doğadaki engel mevsimsel veya mekanik (tozlaştırıcı) gibi çiftleşme/tozlaşma öncesi bir engeldir.'),
  ('Evrimsel hız modelleri açısından, türlerin uzun jeolojik dönemler boyunca çok az değişim gösterip kısa süreli çevresel krizlerde hızlı türleşme patlamaları yaşadığını savunan görüş hangisidir?', 'Sıçramalı (kesintili) denge modeli', ['Yavaş ve tekdüze kademelilik modeli', 'Kazanılmış karakterlerin kalıtımı modeli', 'Sabit türlerin değişmezliği modeli'], 'Niles Eldredge ve Stephen Jay Gould tarafından önerilen sıçramalı (kesintili) denge modeline göre fosil kayıtlarında uzun durağanlık (staz) dönemlerini hızlı türleşme evreleri izler.'),
  ('Türlerin milyonlarca yıl boyunca küçük, kesintisiz ve sabit hızdaki değişimlerin birikmesiyle yavaş yavaş yeni türlere dönüştüğünü öne süren evrimsel model hangisidir?', 'Kademeli evrim (gradualizm) modeli', ['Sıçramalı denge modeli', 'Otopoliploidik ani oluşum modeli', 'Yapay melezleme modeli'], 'Darwin\'in klasik görüşüne dayanan kademeli evrim (filetik gradualizm), türleşmenin uzun zaman dilimlerine yayılan küçük ve sürekli adaptif adımlarla gerçekleştiğini belirtir.'),
  ('Aynı cins içinde yer alan iki tarla faresi türünün kromozom sayılarının sırasıyla 2n=46 ve 2n=54 olması, çiftleştiklerinde doğan sağlıklı yavrunun ise üreme hücresi oluşturamaması hangi mekanizmayla açıklanır?', 'Zigot sonrası melez kısırlığı', ['Zigot öncesi gametik yalıtım', 'Zigot öncesi mekanik yalıtım', 'Zigot sonrası embriyo ölümü'], 'Yavru sağlıklı doğup büyüdüğü için zigot öncesi engeller ve melez yaşayamazlığı aşılmıştır; ancak homolog olmayan kromozom sayıları (23+27=50) mayozu bozduğu için melez kısırlığı görülür.'),
  ('Yaban hardalı (Brassica oleracea) bitkisinden insanlar tarafından seçilerek lahana, brokoli, karnabahar ve brüksel lahanası elde edilmiştir. Görünüşleri çok farklı olan bu bitkiler tozlaştığında verimli tohumlar verebildiğine göre aşağıdakilerden hangisi doğrudur?', 'Tümü hâlâ aynı biyolojik türün alt çeşitleridir', ['Her biri ayrı birer allopoliploid tür haline gelmiştir', 'Aralarında tam bir zigot sonrası üreme engeli vardır', 'Simpatrik türleşme sürecini tamamen tamamlamışlardır'], 'Yapay seçilimle morfolojileri aşırı farklılaşmış olsa da aralarında üreme yalıtımı gelişmediği ve verimli döl verebildikleri için hepsi Brassica oleracea türünün kültür çeşitleridir.'),
  ('Galápagos adalarındaki ispinoz türlerinden birinin sert kabuklu iri tohumları kırmaya yarayan kalın ve güçlü bir gagaya, diğerinin ise ağaç kabuğu altındaki böcekleri çıkarmaya yarayan ince ve uzun bir gagaya sahip olmasının temel evrimsel avantajı nedir?', 'Türler arası besin rekabetini azaltarak farklı ekolojik nişlerden yararlanmayı sağlaması', ['Kuşların tüm adalar arasında her mevsim melezlenerek tek tür kalmasını sağlaması', 'Gaga şekillerinin bireyin yaşam süresi boyunca yediği besine göre uzayıp kısalması', 'Tüm ispinoz türlerinin kromozom sayılarını her kuşakta iki katına çıkarması'], 'Farklı besin kaynaklarına özelleşmiş gagalar, aynı veya komşu adalarda yaşayan türlerin doğrudan rekabetini azaltarak boş nişlerin verimli kullanılmasını (uyumsal açılımı) sağlamıştır.'),
  ('Dinozorların yaklaşık 66 milyon yıl önce kitlesel olarak yok olmasının ardından, o zamana kadar küçük ve gececil olan memelilerin hızla çeşitlenerek balina, yarasa, fil ve aslan gibi çok farklı formlara evrimleşmesi neye örnektir?', 'Kitlesel yok oluş sonrası boşalan ekolojik nişlerde gerçekleşen uyumsal açılıma', ['Farklı sınıflardaki canlıların tek bir türe dönüşmesini sağlayan yakınsak evrime', 'Coğrafi engellerin ortadan kalkmasıyla gen havuzlarının birleşmesine', 'Zigot sonrası melez kısırlığının memelilerde tamamen ortadan kalkmasına'], 'Baskın sürüngen gruplarının yok olmasıyla karada, denizde ve havada boşalan ekolojik nişler, memelilerin küresel ölçekte büyük bir uyumsal açılım geçirmesine olanak tanımıştır.'),
  ('Peter ve Rosemary Grant\'in Galápagos\'taki Daphne Major adasında yürüttüğü uzun süreli araştırmada, şiddetli kuraklık yıllarında küçük ve yumuşak tohumların tükendiği, bir sonraki kuşakta ise ispinoz popülasyonunun ortalama gaga derinliğinin arttığı gözlenmiştir. Bu gözlem neyi doğrudan doğrular?', 'Doğal seçilimin çevresel değişimlere bağlı olarak popülasyonlarda ölçülebilir evrimsel değişim yarattığını', ['Kuraklık stresinin ergin kuşların gagalarını kendi istekleriyle büyütmesine neden olduğunu', 'Bir yıllık kuraklığın ispinozları sürüngenlerle melezlenmeye zorladığını', 'Doğal seçilimin yalnızca yüz milyonlarca yıllık sürelerde etkisini gösterebildiğini'], 'Kalın gagalı bireyler kuraklıkta kalan sert tohumları kırıp hayatta kalarak genlerini aktarmış, böylece doğal seçilimin kısa sürede bile alel frekanslarını değiştirdiği kanıtlanmıştır.'),
  ('Bir deniz memelisi olan yunusun, bir kıkırdaklı balık olan köpekbalığının ve soyu tükenmiş bir deniz sürüngeni olan ihtiyozorun (Ichthyosaurus) su direncini azaltan mekik (hidrodinamik) vücut şekline sahip olması hangi evrimsel olguyla açıklanır?', 'Yakınsak evrim', ['Iraksak evrim', 'Simpatrik poliploidi', 'Melez yaşayamazlığı'], 'Memeli, balık ve sürüngen sınıflarına ait bu üç omurgalı, sucul hayata ayrı ayrı uyum sağlarken benzer fiziksel seçilim baskıları nedeniyle bağımsız olarak benzer mekik gövde formu geliştirmiştir.'),
  ('Boz ayı ile kutup ayısının yakın ortak bir atadan ayrılıp birinin orman ekosistemine uygun koyu post ve hepçil beslenmeye, diğerinin ise buzullara uygun beyaz kürk ve etçil beslenmeye uyum sağlaması aşağıdakilerden hangisine örnektir?', 'Iraksak evrim', ['Yakınsak evrim', 'Analog yapı gelişimi', 'Gametik yalıtım'], 'Yakın akraba olan boz ayı ve kutup ayısının ortak bir atadan ayrılarak farklı habitatlara özgü farklı adaptasyonlar kazanması tipik bir ıraksak evrim örneğidir.'),
  ('İnsan kolu, kedi bacağı, balina yüzgeci ve yarasa kanadı incelendiğinde hepsinin iç iskeletinde aynı sırayla dizilmiş kemiklerin (humerus, radius, ulna, karpal, metakarpal, falanks) bulunması aşağıdakilerden hangisinin en güçlü kanıtıdır?', 'Bu canlıların ortak bir dört üyeli (tetrapod) atadan ıraksak evrimle türediğinin', ['Dört canlının da aynı besin zincirinde otçul tüketici olarak yer aldığının', 'Yakınsak evrimin farklı şubelerdeki kemik sayılarını eşitlediğinin', 'Bu türler arasında doğada hâlâ kesintisiz gen akışının sürdüğünün'], 'Çok farklı görevler (tutma, yürüme, yüzme, uçma) yapmalarına rağmen aynı kemik planını korumaları, bu memelilerin ortak bir atadan ıraksak evrimle çeşitlendiğini (homolojiyi) kanıtlar.'),
  ('Yarasa kanadı ile kuş kanadı karşılaştırıldığında; "dört üyeli omurgalıların ön üyesi olmaları" ve "uçma yüzeyini oluşturan kanat yapıları olmaları" bakımından evrimsel değerlendirmeleri nasıl yapılır?', 'Ön üye kemikleri bakımından homolog, uçmaya yarayan kanat olarak bağımsız geliştikleri için analogdurlar', ['Hem kemik kökeni hem de kanat gelişimi bakımından tamamen körelmiş organlardır', 'Böcek kanatlarıyla aynı kitin dokusundan türedikleri için hiçbir ortak ataları yoktur', 'Ortak uçan bir sürüngen atadan hiç değişmeden kaldıkları için özdeş ikiz yapılardır'], 'Kuşların ve yarasaların ortak atası uçmayan bir dört üyeli omurgalıydı; bu nedenle ön bacak kemikleri homologdur, ancak uçma amaçlı kanat yüzeyleri iki grupta bağımsız evrimleştiği için işlevsel olarak analogdur.'),
  ('Bezelye bitkisinin tutunmaya yarayan sülükleri (bıyıkları) ile kaktüs bitkisinin savunmaya yarayan dikenlerinin her ikisinin de değişime uğramış yaprak olması bu yapıların ne olduğunu gösterir?', 'Homolog yapılar', ['Analog yapılar', 'Körelmiş yapılar', 'Poliploid yapılar'], 'Hem bezelye sülüğü hem de kaktüs dikeni embriyonik olarak yaprak taslağından gelişmiştir; kökenleri aynı (yaprak), görevleri farklı (tutunma ve korunma) olduğu için bitkisel homolog yapılardır.'),
  ('Patatesin toprak altında besin depolayan yumrusu "gövde" kökenli iken, tatlı patatesin besin depolayan yumrusu "kök" kökenlidir. Buna göre patates ve tatlı patates yumruları arasındaki ilişki nedir?', 'Analog yapılardır', ['Homolog yapılardır', 'Körelmiş organlardır', 'Aynı türün klonlarıdır'], 'Biri gövdeden diğeri kökten farklılaştığı için anatomik kökenleri farklıdır; ancak ikisi de toprak altında nişasta depolama işlevi gördüğünden yakınsak evrim ürünü analog yapılardır.'),
  ('Karanlık yeraltı mağaralarında yaşayan kör mağara balıklarında işlevsiz ve deriyle örtülü küçük göz kalıntılarının bulunması evrimsel olarak nasıl açıklanır?', 'Işıksız ortamda görme işlevi seçilim avantajı sağlamadığı için göz yapısının zamanla körelmesiyle', ['Balıkların yaşamları boyunca gözlerini kapatması sonucu kazandıkları özelliğin yavrulara geçmesiyle', 'Mağara sularının balıkların tüm DNA\'sını silerek onları tek hücreli hale getirmesiyle', 'Kör mağara balıklarının gözlü balıklarla hiçbir evrimsel akrabalığının bulunmamasıyla'], 'Mağaraya hapsolan gözlü atalarda görme duyusu avantaj sağlamaz; aksine göz dokusunu geliştirmek enerji maliyeti ve enfeksiyon riski yarattığından doğal seçilim ve mutasyon birikimiyle gözler körelmiştir.'),
  ('Aşağıdakilerden hangisi insan vücudunda evrimsel geçmişe işaret eden körelmiş (vestigial) yapılardan biri olarak kabul edilir?', 'Kuyruk sokumu kemikleri (koksiks) ve kulak kepçesini oynatan kaslar', ['Kanı tüm vücuda pompalayan dört odacıklı kalp kası', 'Akciğerlerde gaz alışverişini sağlayan milyonlarca alveol kesesi', 'Böbreklerde kanın süzülmesini gerçekleştiren nefron kanalları'], 'İnsandaki kuyruk sokumu omurları kuyruklu omurgalı ataların, üçüncü göz kapağı kalıntısı (plica semilunaris), yirmilik dişler ve kulak kasları ise atalarda aktif olan yapıların körelmiş izleridir.'),
  ('Omurgalı hayvan sınıflarına (balık, kurbağa, sürüngen, kuş, memeli) ait erken dönem embriyolarında yutak bölgesinde solungaç keselerinin ve kuyruk yapısının ortak olarak görülmesi neyi gösterir?', 'Omurgalıların ortak bir evrimsel kökenden geldiğini', ['Tüm ergin memelilerin yaşamları boyunca solungaçla su altında solunum yaptığını', 'Embriyonik yapıların yakınsak evrimle sonradan birbirine benzediğini', 'Kuş ve memeliler arasında zigot öncesi üreme engeli bulunmadığını'], 'Ergin halleri çok farklı olan omurgalıların erken embriyonik evrelerinde yutak (solungaç) cepleri ve post-anal kuyruk taşıması, ortak atadan miras alınan gelişimsel gen programlarının kanıtıdır.'),
  ('Biyokimyasal kanıtlar kapsamında, iki farklı hayvan türünün sitokrom-c proteinlerindeki amino asit dizilimlerinin %99 oranında aynı olması aşağıdakilerden hangisini doğrudan destekler?', 'İki türün evrimsel geçmişte yakın bir ortak atayı paylaştığını', ['İki türün kesinlikle aynı besinle beslenip aynı mağarada yaşadığını', 'Bu iki türün çiftleştiğinde her zaman verimli döller üretebildiğini', 'Aralarında yakınsak evrim sonucu analog proteinlerin oluştuğunu'], 'DNA ve protein dizilerindeki yüksek benzerlik (moleküler homoloji), türlerin ortak atadan ayrılmasının üzerinden görece kısa bir evrimsel zaman geçtiğini ve yakın akraba olduklarını gösterir.'),
  ('Atın evrimsel fosil serisi incelendiğinde, ormanlık alanlarda yaşayan çok parmaklı küçük atalardan (Eohippus), açık çayır ve bozkırlarda yaşayan tek toynaklı ve uzun bacaklı modern ata (Equus) geçişte yan parmak kemiklerinin küçülüp "tarak kemiği kalıntısı" haline gelmesi hangi iki kavramı birlikte örneklendirir?', 'Doğal seçilimle adaptasyon ve körelmiş yapı oluşumu', ['Simpatrik poliploidi ve yakınsak evrim', 'Gametik yalıtım ve analog organ gelişimi', 'Melez kısırlığı ve kurucu etkisi'], 'Ormandan açık bozkıra geçişte hızlı koşmayı sağlayan orta parmak seçilimle gelişip toynağa dönüşürken, yere değmeyen yan parmaklar körelmiş kemik kalıntıları olarak kalmıştır.'),
  ('Güney Amerika\'daki devekuşu benzeri "rea", Afrika\'daki "devekuşu" ve Avustralya\'daki "emu" kuşlarının uçamayan iri yapılı yakın akrabalar olması, biyocoğrafik açıdan nasıl açıklanır?', 'Güney kıtaları (Gondwana) birleşikken yaşayan ortak bir atadan kıtaların ayrılmasıyla allopatrik olarak ıraksak evrim geçirmeleriyle', ['Üç kuş türünün de okyanusları yüzerek geçip aynı yılda kanatlarını bırakmasıyla', 'Kuzey Kutbu\'ndaki penguenlerin çöle göç ederek tüylerini uzatmasıyla', 'Aralarında gün aşırı kıtalararası polen ve gamet taşınmasının sürmesiyle'], 'Kıtaların kayması (levha tektoniği), Gondwana\'daki ortak ratit atasını farklı kıtalara ayırmış ve coğrafi yalıtım altında allopatrik türleşme ve ıraksak evrim gerçekleşmiştir.'),
  ('Köpekbalığı yüzgeci, penguen kanadı (yüzgeci) ve yunus yüzgeci üçlüsü bir arada değerlendirildiğinde aşağıdaki ifadelerden hangisi tamamen doğrudur?', 'Penguen ve yunus yüzgeçleri ön üye iskeleti bakımından kendi aralarında homolog, yüzme organı olarak köpekbalığı yüzgeciyle analogdur', ['Üç yapı da aynı kıkırdak dokudan geliştiği için hem köken hem görev bakımından tam homologdur', 'Penguen kanadı ile köpekbalığı yüzgeci uçma kökenli olduğu için körelmiş organlardır', 'Yunus yüzgeci böcek kanadıyla homolog iken penguen kanadıyla hiçbir ortak kemik taşımaz'], 'Penguen (kuş) ve yunus (memeli) dört üyeli omurgalı (tetrapod) oldukları için ön üye kemikleri homologdur; ancak kıkırdaklı balık olan köpekbalığının yüzgeci tetrapod kemik planı taşımaz ve yüzme işlevi yönünden diğerleriyle analogdur.'),
  ('Tortul kayaç katmanları (tabakaları) bozulmamış bir arazide aşağıdan yukarıya (en derinden yüzeye) doğru incelendiğinde fosil kayıtlarında nasıl bir örüntü görülmesi beklenir?', 'Alt katmanlarda daha basit ve eski ata formların, üst katmanlarda ise günümüz türlerine daha yakın ve çeşitlenmiş formların bulunması', ['En derin katmanlarda yalnızca çiçekli bitkilerin ve plasentalı memelilerin fosillerine rastlanması', 'Tüm jeolojik katmanlarda başlangıçtan beri aynı değişmez türlerin eşit oranda dağılması', 'Üst katmanlara çıkıldıkça çok hücreli canlıların yerini tamamen prokaryotların alması'], 'Tortul tabakalar zamanla üst üste biriktiğinden en alt tabakalar en yaşlı dönemleri yansıtır ve yaşamın basitten karmaşığa, ortak atalardan çeşitlenmiş türlere evrimini kronolojik olarak sergiler.'),
  ('Erkek mavi ayaklı sümsük kuşlarının, dişinin önünde parlak mavi ayaklarını sırayla havaya kaldırarak özel bir yürüyüş sergilemesi ve bu dansı yapmayan farklı türden sümsük kuşlarının dişi tarafından reddedilmesi hangi üreme engelidir?', 'Zigot öncesi davranışsal yalıtım', ['Zigot öncesi gametik yalıtım', 'Zigot sonrası melez bozulması', 'Zigot öncesi habitat yalıtımı'], 'Kuşlarda çiftleşme öncesi sergilenen görsel kur dansları türe özgüdür ve farklı türlerle çiftleşmeyi önleyen zigot öncesi davranışsal yalıtımı oluşturur.'),
  ('Avustralya\'da yaşamış keseli kurt (Thylacinus) ile Kuzey Yarımküre\'deki plasentalı gri kurt (Canis lupus) kafatası şekli, diş dizilimi ve avlanma biçimi açısından birbirine çok benzer. Bu iki canlının durumu hangi evrimsel kavram çiftiyle açıklanır?', 'Yakınsak evrim ve analog adaptasyonlar', ['Yakın zamanda gerçekleşmiş simpatrik poliploidi', 'Aralarında devam eden kesintisiz gen akışı', 'Yapay seçilimle evcilleştirme ve melezleme'], 'Keseli kurt bir keseli memeliye (kanguruya), gri kurttan çok daha yakın akrabadır; avcı nişindeki benzer seçilim baskıları iki uzak grupta yakınsak evrimle benzer kafatası ve diş yapısı oluşturmuştur.'),
  ('Kuzey Amerika\'da yaşayan periyodik ağustosböceği türlerinden birinin her 13 yılda bir, diğerinin ise her 17 yılda bir toprak altından çıkıp erginleşerek çiftleşmesi hangi üreme yalıtımının çarpıcı bir örneğidir?', 'Zamansal (mevsimsel/dönemsel) yalıtım', ['Mekanik üreme organı yalıtımı', 'Zigot sonrası melez bozulması', 'Gametik reseptör uyumsuzluğu'], 'Asal sayılar olan 13 ve 17 yıllık yaşam döngüleri yalnızca 221 yılda bir çakışır; üreme dönemlerinin bu denli ayrık olması güçlü bir zamansal (prezigotik) üreme yalıtımı sağlar.'),
  ('Aynı çayırda yaşayan iki farklı örümcek türünde, erkek örümceğin çiftleşme öncesinde dişinin ağına belirli bir frekansta titreşim göndermesi ve yanlış ritimde titreşim gönderen farklı tür erkeğin dişi tarafından av olarak yenmesi hangi yalıtımdır?', 'Davranışsal yalıtım', ['Mevsimsel yalıtım', 'Melez kısırlığı', 'Allopatrik yalıtım'], 'Ağ titreşimleriyle yapılan türe özgü kur sinyali, eş tanımayı sağlayan davranışsal bir zigot öncesi üreme engelidir.'),
  ('Adaçayı (Salvia) cinsine ait iki bitki türünden birinin çiçek yapısı poleni arının sırtına, diğerinin çiçek yapısı ise poleni arının karın altına bulaştıracak şekilde kıvrılmıştır. Bir çiçekten diğerine giden arının poleni diğer türün dişicik tepesine değdirememesi hangi yalıtımdır?', 'Mekanik yalıtım', ['Zamansal yalıtım', 'Melez yaşayamazlığı', 'Melez bozulması'], 'Çiçeklerin anatomik ve yapısal (morfolojik) farklılığı nedeniyle polen transferinin fiziksel olarak gerçekleşememesi mekanik yalıtımın bitkilerdeki klasik örneğidir.'),
  ('Rüzgârla tozlaşan bir mısır tarlasına yakındaki yabani çiçeklerin polenleri bolca ulaşmasına rağmen, yabancı polenlerin mısır püskülü üzerinde polen tüpü oluşturamaması hangi üreme engelini gösterir?', 'Zigot öncesi gametik yalıtım', ['Zigot öncesi davranışsal yalıtım', 'Zigot sonrası melez kısırlığı', 'Zigot sonrası embriyo ölümü'], 'Tozlaşma (polenin taşınması) gerçekleştiği halde polen tüpünün kimyasal/moleküler uyumsuzluk nedeniyle çimlenememesi ve yumurtaya ulaşamaması bitkilerde gametik yalıtımdır.'),
  ('Aynı coğrafi bölgedeki bir parazit bitki biti popülasyonunun bir kısmının yalnızca meşe ağaçlarında, diğer kısmının ise yalnızca ceviz ağaçlarında beslenip kendi konak ağacının yaprakları üzerinde çiftleşmesi hangi yalıtımı başlatır?', 'Habitat (ekolojik) yalıtımı', ['Melez kısırlığı yalıtımı', 'Kıtasal allopatrik yalıtım', 'Gametik antijen yalıtımı'], 'Aynı coğrafyada bulunsalar bile farklı konak türlerini yaşam ve üreme alanı olarak seçmeleri bireylerin karşılaşmasını önleyen ekolojik (habitat) yalıtımdır ve simpatrik türleşmeye zemin hazırlar.'),
  ('Dallandırıcı (çeşitlendirici/yıkıcı) doğal seçilimin bir popülasyonda uzun süre etkili olması, türleşme açısından nasıl bir sonuç doğurmaya en yatkındır?', 'Ortalama fenotipleri eleyip iki uç fenotipi destekleyerek popülasyonu alt gruplara ayırmaya', ['Tüm uç varyasyonları eleyerek popülasyonu tek bir ortalama fenotipte sabitlemeye', 'Popülasyondaki kalıtsal varyasyonu sıfırlayarak tüm bireyleri genetik ikiz yapmaya', 'Kromozomlardaki tüm genlerin dizilimini ata türün ilk haline geri döndürmeye'], 'Dallandırıcı seçilim (örneğin hem çok küçük hem çok büyük gagalı kuşların avantajlı olup orta gagalıların dezavantajlı olması), popülasyonu iki farklı ekolojik nişe yönlendirerek türleşmeyi teşvik eder.'),
  ('Yunuslarda burun deliğinin evrimsel süreçte kafatasının ucundan başın üst kısmına (hava deliğine) doğru yer değiştirdiğini gösteren fosil serisi aşağıdakilerden hangisini doğrudan kanıtlar?', 'Deniz memelilerinin burunları önde olan karasal memeli atalardan kademeli olarak evrimleştiğini', ['Yunusların solungaç yarıklarıyla su altındaki çözünmüş oksijeni soluduğunu', 'Balıkların pullarının dökülmesiyle bir gecede yunus sürülerinin oluştuğunu', 'Kafatası kemiklerinin her yunus yavrusunda yetişkinlikte yer değiştirdiğini'], 'Pakicetus ve Ambulocetus gibi erken balina/yunus atalarında burun öndeyken, ara fosillerde kademeli olarak tepeye kaymış olması karadan suya geçişteki morfolojik adaptasyonu belgeler.'),
  ('Soğan bitkisinin toprak altındaki etli ve besin depolayan katmanları ile bezelye bitkisinin fotosentez yapan yeşil yaprakları anatomik köken ve görev açısından karşılaştırıldığında hangisi doğrudur?', 'İkisi de yaprak kökenli olup farklı görevlere uyum sağlamış homolog yapılardır', ['Biri kök diğeri çiçek kökenli olduğu için yakınsak evrim ürünü analog yapılardır', 'Her iki yapı da bitkilerde hiçbir görevi kalmamış körelmiş organlardır', 'Soğan katmanları mantar hiflerinden geliştiği için bitkisel doku içermez'], 'Soğanın etli katmanları besin depolamak üzere değişime uğramış yapraklardır; bezelyenin yeşil yaprağıyla aynı embriyonik kökenden (yaprak taslağından) gelip farklı görev üstlendiği için homologdur.'),
  ('Akasya ağacındaki koruyucu dikenlerin "yaprak kulakçığı" kökenli, alıç ve limon ağaçlarındaki dikenlerin "yan dal (gövde)" kökenli, gül bitkisindeki dikenlerin ise "epidermis çıkıntısı" kökenli olması bu dikenlerin birbirine göre ne olduğunu kanıtlar?', 'Benzer savunma işlevi gören analog yapılar olduklarını', ['Aynı gen dizisinden türemiş özdeş homolog organlar olduklarını', 'Bitkilerde su iletimini sağlayan körelmiş kök tüyleri olduklarını', 'Yalnızca allopoliploid bitkilerde görülen melez kısırlık yapıları olduklarını'], 'Farklı bitki gruplarında otçullara karşı korunma (savunma) amacıyla yaprak, gövde veya epidermis gibi farklı dokulardan bağımsız olarak gelişen dikenler yakınsak evrim ürünü analog yapılardır.'),
  ('Penguenler (Güney Yarımküre) ile soyu tükenmiş büyük dalgıç kuşları / alklar (Kuzey Yarımküre), farklı kuş takımlarına ait olmalarına rağmen siyah-beyaz tüy desenleri, dik duruşları ve yüzgeç gibi kullandıkları kanatlarıyla birbirine çok benzerdi. Bu benzerliğin temel sebebi nedir?', 'Soğuk denizlerde dalıp balık avlama nişine sağlanan yakınsak evrimsel uyum', ['Güney Kutbu penguenlerinin her yaz Kuzey Kutbu\'na uçarak melezlenmesi', 'İki grubun da aynı adada poliploidi yoluyla tek bir yumurtadan çıkması', 'Kuş kanatlarının su ile temas ettiğinde bir mevsimde yüzgece dönüşmesi'], 'Farklı yarımkürelerdeki soğuk okyanuslarda benzer sualtı avcılığı nişini dolduran iki ayrı kuş soyunun benzer hidrodinamik ve kamuflaj özellikleri kazanması yakınsak evrimdir.'),
  ('Madagaskar yıldız orkidesinin yaklaşık 30 cm uzunluğundaki nektar mahmuzuna yalnızca 30 cm uzunluğunda hortumu olan bir şahin güvesi türünün ulaşabilmesi, orkide açısından üreme yalıtımına nasıl katkıda bulunur?', 'Polenlerin yalnızca aynı orkide türünü ziyaret eden özelleşmiş güveyle taşınmasını sağlayarak mekanik/ekolojik yalıtımı güçlendirir', ['Orkidenin tohumlarının rüzgârla tüm kıtalara yayılmasını sağlayarak poliploidiyi engeller', 'Güve ile orkide hücrelerinin birleşerek hayvan-bitki melezi oluşturmasını sağlar', 'Orkidenin yılın her günü farklı bir böcek takımıyla rastgele tozlaşmasını hızlandırır'], 'Aşırı özelleşmiş tozlaştırıcı ilişkisi, polenin farklı bitki türlerine gidip ziyan olmasını önler ve türler arası gen karışımını engelleyen güçlü bir zigot öncesi (mekanik/davranışsal) bariyer işlevi görür.'),
  ('Bir adada yalnızca çok küçük yumuşak tohumlar ve çok büyük sert tohumlar üreten iki bitki türü kalmış, orta boy tohum üreten bitkiler ise bir hastalıkla yok olmuştur. Bu adadaki tohumcul bir kuş popülasyonunda uzun vadede ne beklenir?', 'Orta büyüklükte gagalı kuşların elenip küçük ve büyük gagalı iki alt grubun belirginleşmesi', ['Tüm kuşların orta büyüklükte tek tip gagaya sahip olacak şekilde tekdüzeleşmesi', 'Kuşların tamamının gagalarının dökülerek körelmiş organ haline gelmesi', 'Kuşların bitkilerle gametik yalıtım geliştirerek fotosentez yapmaya başlaması'], 'Besin kaynağının iki uca ayrılması dallandırıcı (çeşitlendirici) seçilim yaratır; orta gagalı bireyler her iki tohumda da verimsiz kalırken iki uçtaki uzmanlaşmış gagalar seçilir.'),
  ('Evrimsel gelişim biyolojisinde (evo-devo), meyve sineğinden (Drosophila) fareye ve insana kadar çok farklı hayvan şubelerinde vücudun baş-kuyruk eksenindeki organ dizilimini kontrol eden "Hox genleri"nin yüksek oranda benzer dizilere sahip olması neyi kanıtlar?', 'İki yanlı bakışımlı (bilateral) hayvanların yüz milyonlarca yıl önceki ortak atadan aynı temel gelişim araç kutusunu miras aldığını', ['Meyve sinekleri ile farelerin doğada çiftleşerek verimli melezler üretebileceğini', 'Sinek kanatları ile fare bacaklarının hiçbir genetik düzenlemeye ihtiyaç duymadığını', 'Yakınsak evrimin tüm hayvanların kromozom sayılarını 46\'da eşitlediğini'], 'Derin homoloji (deep homology) olarak adlandırılan Hox gen ailesi korunumu, çok farklı görünen hayvan vücut planlarının ortak bir atadaki genetik kontrol sisteminin değiştirilmesiyle evrimleştiğini kanıtlar.'),
  ('Denizde yaşayan bazı mercan türleri yılın yalnızca belirli bir dolunay gecesinde ve belirli bir su sıcaklığında aynı saatte suya yumurta ve sperm bırakır; komşu mercan türü ise bundan iki ay sonraki dolunayda üreme hücresi bırakır. Bu mercanlar arasındaki temel engel hangisidir?', 'Zamansal yalıtım', ['Davranışsal kur yalıtımı', 'Mekanik kabuk yalıtımı', 'Melez bozulması'], 'Suya serbest gamet bırakan deniz omurgasızlarında gamet salım zamanlarının farklı ay veya gecelerde olması doğrudan zamansal (mevsimsel) üreme yalıtımıdır.'),
  ('Erkek cennet kuşlarının son derece gösterişli tüylerini kabartıp karmaşık ritmik figürler sergilemesi, ancak kendi türünün dişileri tarafından kabul görmesini sağlarken yakın akraba diğer cennet kuşu dişilerinin ilgisini çekmemektedir. Bu durumun evrimsel sonucu nedir?', 'Eşeysel seçilim yoluyla davranışsal üreme yalıtımının korunması ve tür sınırlarının netleşmesi', ['Farklı cennet kuşu türleri arasında melezleşmenin her kuşakta katlanarak artması', 'Gösterişli tüylerin avcıları uzaklaştırarak kuşların ömrünü sonsuza dek uzatması', 'Kuş popülasyonlarında tüm genetik çeşitliliğin bir nesilde tamamen yok olması'], 'Dişilerin türe özgü kur gösterilerini ve tüy desenlerini seçmesi (eşeysel seçilim), türler arası çiftleşmeyi engelleyen güçlü bir davranışsal yalıtım oluşturur.'),
  ('Aşağıdaki eşleştirmelerden hangisinde verilen iki canlı arasındaki benzerlik "ıraksak evrim / ortak yakın ata" yerine "yakınsak evrim / benzer çevreye uyum" ile açıklanır?', 'Yunus (memeli) ile penguenin (kuş) aerodinamik/hidrodinamik gövde ve yüzgeç biçimi', ['Aslan ile kaplanın et parçalamaya uyumlu kesici dişleri ve geri çekilebilir pençeleri', 'Şempanze ile gorilin kavrayıcı başparmak yapıları ve yassı tırnakları', 'At ile zebranın tek toynaklı bacak iskeletleri ve otçul azı dişleri'], 'Aslan-kaplan, şempanze-goril ve at-zebra çiftleri çok yakın akraba olup benzerlikleri ortak atadan (homoloji) gelir; yunus ve penguen ise farklı sınıflarda olup benzer sucul avcı formunu yakınsak evrimle kazanmıştır.'),
  ('Güney Amerika\'daki dev karıncayiyen (memeli), Afrika\'daki pangolin (farklı memeli takımı) ve Avustralya\'daki dikenli karıncayiyen/ekidne (yumurtlayan memeli); uzun yapışkan dilleri, dişsiz tüp burunları ve güçlü kazıcı pençeleriyle karınca/termit yuvalarıyla beslenir. Üç farklı kıtadaki bu uzak akraba memelilerin çarpıcı benzerliği neyi kanıtlar?', 'Karınca ve termitle beslenme (mirmekofaji) nişinin farklı kıtalarda yakınsak evrimle benzer morfolojileri seçtiğini', ['Üç hayvanın da geçtiğimiz yüzyılda insanlar tarafından melezlenerek üretildiğini', 'Yumurtlayan memelilerin doğrudan pangolinlerin yavrusu olduğunu', 'Coğrafi yalıtımın farklı kıtalardaki canlıları her zaman birbirinden tamamen zıt şekillere soktuğunu'], 'Farklı memeli soylarının ayrı kıtalarda aynı özel besin kaynağına (karınca/termit kolonilerine) uyum sağlarken bağımsız olarak uzun yapışkan dil, tüp ağız ve güçlü pençe geliştirmesi yakınsak evrimin en ünlü örneklerindendir.'),
  ('Çiçekli bitkilerde yabani diploit (2n=12) bir tür ile başka bir yabani diploit (2n=16) türün doğada tozlaşması sonucu oluşan 14 kromozomlu melez bitki başlangıçta kısırken, meristem dokusundaki bir mitoz ayrılmamasıyla 28 kromozomlu dallar oluşturduğunda yeniden verimli tohum üretebilmesinin nedeni nedir?', 'Her kromozomun mayozda eşleşebileceği özdeş bir homolog eşe kavuşmuş olması', ['Bitkinin eşeyli üremeyi tamamen terk edip yalnızca sporla üremeye başlaması', 'Kromozom sayısı 28 olunca bitkinin ata türlerle aynı gen dizisine dönmesi', 'Polenlerin artık yumurta hücresi olmadan tek başına meyve oluşturması'], '14 kromozomlu melezde (6+8) kromozomların homolog eşi olmadığı için mayoz bozulur; kromozom seti ikiye katlandığında (12+16=28) her kromozom kendi eşini bulur ve düzenli mayozla verimli yeni allopoliploid tür doğar.'),
  ('Böcekçil bitkilerden "Venüs sinekkapanı"nın kapan şeklindeki yaprakları, "ibrik otu"nun sindirim sıvısı dolu sürahi şeklindeki yaprakları ve "güneşgülü"nün yapışkan tüylü yaprakları azotça fakir bataklık topraklarında böcek yakalamaya yarar. Bu üç bitkinin kapan yapıları, yaprak kökenli olmaları açısından nasıl değerlendirilir?', 'Temel organ kökeni bakımından yaprakla homolog, böcek yakalama adaptasyonu açısından farklılaşmış yapılardır', ['Hayvanların mide dokusundan yatay gen aktarımıyla alınmış körelmiş organlardır', 'Kök tüylerinin çiçek taç yapraklarıyla birleşmesinden doğmuş kısır melez yapılardır', 'Azotça zengin çöl topraklarında su depolamak için gelişmiş gövde yumrularıdır'], 'Böcekçil bitkilerdeki tuzakların tamamı fotosentetik yaprak taslağının evrimsel süreçte değişime (modifikasyon değil, kalıtsal uyarlanmaya) uğramasıyla gelişmiş homolog yaprak türevleridir.'),
  ('Kuzey Kutbu\'ndaki kutup ayısı (Ursus maritimus) ile Kuzey Amerika\'daki boz ayı (Ursus arctos) doğada farklı yaşam alanlarında bulunur; ancak iklim değişikliğiyle yaşam alanları kesiştiğinde çiftleşip doğurgan "pizzly/grolar" melezleri üretebilmektedir. Bu durum biyolojik tür kavramı açısından neyi ortaya koyar?', 'Yakın zamanda ayrılmış türler arasında üreme yalıtımının henüz tam olarak tamamlanmamış olabileceğini', ['Kutup ayısı ile boz ayının farklı şubelere ait olup yakınsak evrimle benzediğini', 'Zigot sonrası engellerin doğada her zaman zigot öncesi engellerden önce oluştuğunu', 'Memeli hayvanlarda hiçbir zaman allopatrik türleşmenin gerçekleşemediğini'], 'Evrim sürekli bir süreç olduğundan, ortak atadan görece yakın geçmişte (yaklaşık 400-500 bin yıl önce) ayrılmış türler ekolojik ve davranışsal olarak ayrılsalar bile tam genetik kısırlığa henüz ulaşmamış olabilirler.'),
  ('Sürüngenlerin alt çenesinin birden fazla kemikten oluşup orta kulaklarında tek kemik (üzengi) bulunması, memelilerin ise alt çenesinin tek kemikten oluşup orta kulaklarında üç kemik (çekiç, örs, üzengi) bulunması fosil kayıtlarında nasıl bağlanmıştır?', 'Memeli benzeri sürüngen fosillerinde (sinapsitler) arka çene kemiklerinin küçülerek orta kulağa göç ettiğinin görülmesiyle', ['Memelilerin kulak kemiklerinin böcek antenlerinden yakınsak evrimle geliştiğinin bulunmasıyla', 'Sürüngenlerdeki çene kemiklerinin tamamının eriyip hiçbir iz bırakmadan yok olmasıyla', 'Kuşların gagalarındaki tüm kemiklerin memeli kafatasına sonradan eklenmesiyle'], 'Sinapsit ara fosilleri ve embriyolojik gelişim, atasal sürüngen çene eklemini oluşturan kuadrat ve artiküler kemiklerin memelilerde işitme hassasiyetini artıran örs ve çekiç kemiklerine (homolog yapılara) dönüştüğünü kanıtlamıştır.'),
  ('Galápagos adalarındaki "kaktüs ispinozu"nun uzun ve sivri gagası kaktüs çiçeklerinden nektar ve polen almaya, "yer ispinozu"nun kısa ve kalın gagası ise yerdeki sert tohumları kırmaya uyumludur. Aynı adada yaşayan bu iki türün kendi aralarında çiftleşmemesinde gaga şeklinin yanı sıra hangi mekanizma doğrudan rol oynar?', 'Gaga yapısının çıkardığı türe özgü ötüş sesi ve görsel eş tanıma (davranışsal yalıtım)', ['Kaktüs polenlerinin ispinoz yumurtalarını dölleyerek melezliği önlemesi (gametik yalıtım)', 'Kuşların kromozom sayılarının her kurak mevsimde yarıya inmesi (poliploidi)', 'Bir türün yalnızca su altında, diğerinin bulutların üzerinde yuva yapması'], 'Grant çiftinin araştırmaları, Galápagos ispinozlarında hem gaga morfolojisinin (görsel ipucu) hem de gaga boyutunun şekillendirdiği türe özgü ötüş şarkılarının güçlü bir davranışsal üreme engeli oluşturduğunu göstermiştir.'),
  ('Fok balığının yüzmeye yarayan ön yüzgeci ile atın koşmaya yarayan ön bacağı arasındaki evrimsel ilişki aşağıdakilerden hangisinde doğru verilmiştir?', 'Ortak memeli atasından ıraksak evrimle farklılaşmış homolog organlardır', ['Farklı hayvan şubelerinden yakınsak evrimle gelişmiş analog organlardır', 'Her ikisi de işlevini tamamen yitirmiş körelmiş embriyonik yapılardır', 'At bacağı kemikli, fok yüzgeci kitin yapılı olduğu için akraba değillerdir'], 'Fok ve at plasentalı memelilerdir; biri suda yüzmeye, diğeri karada koşmaya uyum sağlamış olsa da ön üyelerindeki kemik planı ortak atadan miras alınan homolojiyi yansıtır.'),
  ('Böceklerin pek çok türünde erkek ve dişi dış üreme organları yalnızca kendi türünün bireyleriyle tam kenetlenecek şekilde karmaşık kitin çıkıntılara sahiptir. Bu "kilit-anahtar" modelinin böceklerde çok yaygın olmasının evrimsel işlevi nedir?', 'Yakın akraba türlerle hatalı çiftleşmeleri fiziksel olarak önleyerek mekanik üreme yalıtımı sağlamak', ['Böceklerin kurak mevsimlerde su kaybını önleyerek çöl ortamında fotosentez yapmasını sağlamak', 'Farklı böcek takımları arasında gen alışverişini hızlandırarak melez çeşitliliğini artırmak', 'Yumurtadan çıkan larvaların kromozom sayısını her nesilde iki katına çıkarmak'], 'Tür çeşitliliği çok yüksek olan böceklerde dış genital yapıların hızlı farklılaşması, aynı ortamda yaşayan yakın akraba türler arasında mekanik yalıtım sağlayarak gamet israfını önler.'),
  ('İnsan kolundaki pazu kemiği (humerus) ile kuş kanadındaki pazu kemiğinin (humerus) varlığı evrimsel olarak neyi kanıtlarken, kuş kanadı ile yusufçuk böceğinin kanadı neyi kanıtlar?', 'Birincisi ortak atadan ıraksak evrimi (homoloji), ikincisi benzer işleve yakınsak evrimi (analoji) kanıtlar', ['Birincisi yakınsak evrimi, ikincisi ortak böcek atasından ıraksak evrimi kanıtlar', 'Her iki karşılaştırma da canlılarda hiçbir zaman türleşme olmadığının kanıtıdır', 'Birincisi melez kısırlığını, ikincisi simpatrik poliploidiyi kanıtlar'], 'İnsan ve kuş dört üyeli omurgalı ortak atasından humerus kemiğini miras almıştır (homolog); kuş ve yusufçuk ise uçma işlevini bağımsız evrimleştirmiştir (analog).'),
  ('Darboğaz etkisine veya kurucu etkisine maruz kalmış küçük ve izole bir ada popülasyonunda allopatrik türleşmenin büyük ana kara popülasyonlarına göre daha hızlı gerçekleşebilmesinin temel nedeni nedir?', 'Genetik sürüklenmenin ve yeni seçilim baskılarının küçük gen havuzunda alel frekanslarını çok daha hızlı değiştirmesi', ['Küçük popülasyonlarda DNA polimeraz enziminin her hücre bölünmesinde çalışmayı durdurması', 'Ada ortamında yaşayan bireylerin aralarında her türlü gen akışının tamamen yasaklanması', 'Ana karadaki büyük popülasyonlarda doğal seçilimin hiçbir zaman işlev görmemesi'], 'Küçük izole popülasyonlarda hem rastgele genetik sürüklenme nadir alelleri hızla sabitleyebilir hem de adanın özgün ekolojik koşulları gen havuzunu kısa sürede yeniden şekillendirir.'),
  ('Yılan balığı (kemikli balık), deniz yılanı (sürüngen) ve taşemen/lamprey (çenesiz omurgalı) ince, uzun, silindirik ve uzuvsuz vücut biçimlerine sahiptir. Üç farklı omurgalı sınıfına ait bu canlıların dış görünüş benzerliği hangi evrimsel süreçle açıklanır?', 'Dar yarıklarda ve su içinde kıvrılarak hareket etmeye uyum sağlayan yakınsak evrimle', ['Üç türün de geçtiğimiz bin yılda aynı yılan türünden poliploidiyle türemesiyle', 'Aralarında doğada verimli melezler oluşturan sürekli gen akışı bulunmasıyla', 'Omurgalıların tamamının başlangıçta kara yılanı olarak ortaya çıkmasıyla'], 'Çenesiz balık, kemikli balık ve sürüngen sınıflarında bağımsız olarak uzuvsuz ve yılanvari gövde biçiminin gelişmesi benzer hareket nişine yönelik yakınsak evrimdir.'),
  ('Meyve yarasaları ile insanların her ikisinde de C vitamini sentezleyen GULO geninin işlevsiz olması, ancak genetik analizlerde insandaki mutasyonlarla meyve yarasasındaki mutasyonların genin farklı bölgelerinde ve farklı zamanlarda oluştuğunun saptanması nasıl yorumlanır?', 'Meyvece zengin diyet nedeniyle C vitamini sentez kaybının iki memeli grubunda bağımsız (yakınsak) olarak gerçekleştiği', ['İnsanların ve meyve yarasalarının diğer tüm memelilerden daha yakın ikiz kardeş türler olduğu', 'Meyve yarasalarının insanlardan kan emerek bozuk GULO genini virüslerle kopyaladığı', 'GULO geninin yalnızca etçil sürüngenlerde işlevsiz bir psödogen olarak bulunduğu'], 'İnsan ve şempanzedeki özdeş GULO mutasyonu ortak primat atasını (homolojiyi) kanıtlarken, uzak akraba meyve yarasasında farklı bir mutasyonla aynı genin bozulması benzer meyve diyeti altında bağımsız gen kaybını (yakınsak körelmeyi) gösterir.'),
  ('Biyocoğrafya kanıtlarına göre, okyanus ortasındaki izole volkanik adalarda (örneğin Galápagos veya Hawaii) doğal olarak bulunan yerli (endemik) türlerin en yakın akrabalarının genellikle nerede yaşadığı saptanmıştır?', 'Adaya coğrafi olarak en yakın olan ana kara kıyılarında', ['Dünyanın tam karşı yarımküresindeki yüksek dağ zirvelerinde', 'Okyanus tabanındaki ışıksız hidrotermal baca ekosistemlerinde', 'Ada ile aynı enlemde bulunan ancak binlerce kilometre uzaktaki çöllerde'], 'Darwin\'in Galápagos gözlemlerinde belirttiği gibi, okyanus adalarının canlıları iklimi benzeyen uzak kıtalardaki türlere değil, göçle (kurucu etkisiyle) geldikleri en yakın ana karadaki (Güney Amerika) türlere genetik ve morfolojik olarak daha yakındır.'),
  ('Haldane Kuralı\'na göre, iki farklı hayvan türünün çaprazlanmasıyla oluşan F1 melez kuşakta cinsiyetlerden yalnızca biri kısır ya da yaşayamaz oluyorsa, bu durum hemen her zaman hangi cinsiyette görülür?', 'Heterogametik (örneğin memelilerde XY erkek, kuş ve kelebeklerde ZW dişi) olan cinsiyette', ['Yalnızca vücut ağırlığı daha fazla olan dişi memeli ve kraliçe arı bireylerinde', 'Her zaman homogametik (memelilerde XX, kuşlarda ZZ) olan cinsiyette', 'Yalnızca dış döllenme yapan balıkların haploit kromozomlu bireylerinde'], 'J.B.S. Haldane tarafından keşfedilen bu evrimsel kurala göre, çekinik uyumsuz eşey kromozomu alelleri heterogametik cinsiyette (XY veya ZW) karşı eş kromozom tarafından maskelenemediği için melez kısırlığı/ölümü önce o cinsiyette ortaya çıkar.'),
  ('Aşağıdaki yapılardan hangisi insan ile şempanzenin yakın evrimsel akrabalığını destekleyen "moleküler homoloji" kanıtları arasında yer alır?', 'Hemoglobin proteinini oluşturan beta zincirindeki 146 amino asidin tamamının iki türde aynı dizilime sahip olması', ['İki türün de ağaç dallarına tutunurken ya da yürürken arka üyelerini kullanabilmesi', 'Her iki türün de tropikal yağmur ormanlarında meyve ve yapraklarla beslenebilmesi', 'Şempanze ve insan gözlerinin ışığı algılamak için mercek kullanması'], 'Proteinlerin amino asit dizilimi ve DNA baz dizilimlerindeki özdeşlik veya çok yüksek benzerlik doğrudan moleküler homoloji kanıtıdır.'),
  ('Bir adaya taşınan tek bir kertenkele türünün milyonlarca yıl içinde; bir türünün ağaç tepelerindeki ince dallarda yaşayan kısa bacaklı forma, diğerinin ağaç gövdesinde yaşayan orta bacaklı forma, üçüncüsünün ise yerdeki çimenlerde yaşayan uzun bacaklı forma dönüşmesi (Karayip Anolis kertenkeleleri) hangi süreçlerin birleşimidir?', 'Uyumsal açılım, ekolojik niş paylaşımı ve habitat yalıtımı', ['Simpatrik otopoliploidi ve zigot sonrası F2 çöküşü', 'Uzak kıtalardaki amfibilerle gerçekleşen melezleşme', 'Tüm kertenkele uzuvlarının körelerek yılana dönüşmesi'], 'Karayip adalarındaki Anolis kertenkeleleri, aynı ağaç ve çayır ekosistemini farklı mikrohabitatlara (taç, gövde, zemin) bölerek rekabeti azaltmış, uyumsal açılım ve habitat yalıtımıyla çok sayıda türe ayrılmıştır.'),
  ('Yılanların çoğunda sol akciğerin tamamen kaybolmuş veya işlevsiz küçücük bir kese halinde kalmış olması, sağ akciğerin ise ince uzun gövde boyunca uzanması hangi iki evrimsel kavramla açıklanır?', 'Sol akciğer için körelmiş yapı, sağ akciğer için dar vücut planına morfolojik adaptasyon', ['Sol akciğer için analog organ, sağ akciğer için zigot öncesi mekanik yalıtım', 'Her iki akciğer için de balık solungaçlarıyla yakınsak evrimsel özdeşlik', 'Yılanlarda solunum sisteminin tamamen deri yüzeyine geçmesiyle oluşan poliploidi'], 'İnce silindirik yılan gövdesinde iki yan yana akciğer yer kaplayacağından sağ akciğer boyuna uzayarak uyum sağlamış, sol akciğer ise atasal sürüngenlerden kalan körelmiş bir kese haline inmiştir.'),
  ('Deniz memelisi olan balinanın su altında nefesini uzun süre tutabilmesini sağlayan kaslarındaki yüksek miyoglobin proteini ile dalıcı bir kuş olan imparator penguenin kaslarındaki yüksek miyoglobin adaptasyonu karşılaştırıldığında hangisi doğrudur?', 'Miyoglobin geni ortak omurgalı atasından miras alınmış (homolog), ancak yüksek konsiyentrasyon ve net yüzey yükü artışı derin dalışa uyum olarak yakınsak evrimleşmiştir', ['Balina ve penguen kaslarında oksijen bağlayan moleküllerin tamamı klorofil türevi analog pigmentlerdir', 'İmparator penguenler bu geni balinalarla çiftleşerek melezleme yoluyla kazanmıştır', 'Derin dalış yapan hayvanlarda miyoglobin proteini işlevini yitirmiş körelmiş bir moleküldür'], 'Tüm omurgalılarda miyoglobin geni homologdur; ancak derin dalan memeli ve kuşlarda proteinin birbirine yapışmadan yüksek miktarda depolanmasını sağlayan pozitif yüzey yükü artışları yakınsak olarak evrimleşmiştir.'),
  ('Kuşların ön üyelerindeki parmak kemiklerinin kaynaşıp azalarak uçuş tüylerini destekleyen sert bir kanat iskeleti oluşturması, yarasalarda ise dört parmak kemiğinin aşırı uzayarak aralarında esnek uçuş derisini germesi hangi gerçeği açıkça ortaya koyar?', 'Ortak beş parmaklı ön üye planının (homoloji), kuş ve yarasada uçma işlevini (analoji) sağlamak üzere iki farklı mimari yolla şekillendiğini', ['Yarasa kanadının tüylü kuş kanadının yaşlanarak dökülmüş körelmiş bir biçimi olduğunu', 'Kuşların ve yarasaların aynı uçan dinozor türünden hiçbir kemik değişimi geçirmeden türediğini', 'Beş parmaklı el iskeletinin yalnızca sucul balık sınıflarında ilk kez ortaya çıktığını'], 'Bu karşılaştırma homoloji ve analojinin düzey farkını mükemmel özetler: Ön üye kemikleri tetrapod atadan dolayı homologdur, fakat kanat yüzeyini oluşturma biçimleri bağımsız evrimleştiği için analogdur.'),
  ('Çöl ortamında yaşayan deve (memeli) ile devekuşunun (kuş) kum fırtınalarından gözlerini koruyan uzun kirpiklere ve kumda batmayı önleyen geniş tabanlı iki parmaklı ayak yapısına sahip olması nasıl açıklanır?', 'Benzer çöl ve kumul ortamının farklı omurgalı sınıflarında seçtiği yakınsak adaptasyonlarla', ['Deve ile devekuşunun ortak çöl atasından yakın zamanda ayrılmış kardeş türler olmasıyla', 'Devekuşunun memeliler sınıfından ayrılarak sonradan tüy ve gaga geliştirmesiyle', 'İki tür arasında çöl vahalarında gerçekleşen mevsimsel gen akışıyla'], 'Deve bir çift toynaklı memeli, devekuşu ise uçamayan bir kuştur; kumul yaşamının yarattığı benzer fiziksel zorluklar iki uzak grupta yakınsak evrimle benzer koruyucu adaptasyonların seçilmesini sağlamıştır.'),
  ('Yabani hardal bitkisinden (Brassica oleracea) insanların farklı kısımları seçerek üretmesi sonucunda lahana, brokoli, karnabahar, Brüksel lahanası ve yer lahanasının elde edilmiş olması neyi kanıtlar?', 'Yapay seçilimin tek bir atasal türden kısa sürede çarpıcı morfolojik çeşitlilik üretebildiğini', ['Farklı sebze türlerinin birbirleriyle hiçbir ortak gen taşımadan ayrı ayrı yaratıldığını', 'Toprağa eklenen gübre çeşitlerinin yabani hardalda kalıtsal olmayan modifikasyonlar yaptığını', 'Dengeleyici seçilimin bitkilerdeki yaprak ve çiçek tomurcuğu yapılarını sabit tuttuğunu'], 'İnsanlar yabani hardalın tepe tomurcuğunu seçerek lahanayı, çiçek kümelerini seçerek karnabahar ve brokoliyi yapay seçilimle aynı türden türetmiştir.'),
  ('Batı Afrika\'da yaşayan siyah karınlı tohum kırma ispinozlarında (Pyrenestes ostrinus) yalnız çok yumuşak ve çok sert saz tohumlarının bulunduğu bölgelerde küçük gagalı ve büyük gagalı kuşların yaygın olması, orta büyüklükte gagalı kuşların ise her iki tohumu da verimli kıramadığı için nadir görülmesi hangi seçilim örneğidir?', 'Dallandırıcı seçilim', ['Dengeleyici seçilim', 'Yönlü seçilim', 'Eşeysel seçilim'], 'Orta boy gagalı bireyler yumuşak tohumlarda küçük gagalılarla, sert tohumlarda büyük gagalılarla rekabet edemediğinden elenir ve iki uç fenotip korunur.'),
  ('Aynı türe ait erkek ve dişi bireylerin vücut büyüklüğü, renk, boynuz veya yele gibi ikincil eşey karakterleri bakımından belirgin dış görünüş farklılıkları göstermesine "eşeysel dimorfizm" denir. Bu olguyu şekillendiren birincil evrimsel mekanizma hangisidir?', 'Eşeysel seçilim', ['Dengeleyici seçilim', 'Yapay seçilim', 'Nötr mutasyonlar'], 'Aslanlarda yele, geyiklerde boynuz, kuşlarda tüy parlaklığı gibi eşeyler arası morfolojik farklar eş bulma rekabeti ve eş tercihi (eşeysel seçilim) sonucu gelişmiştir.'),
  ('Dişi cennet kuşlarının, tüylerini kabartıp karmaşık dans figürleri sergileyen erkekleri izleyerek en simetrik ve ritmik dans edeni çiftleşmek üzere seçmesi hangi mekanizmaya örnektir?', 'Eşeyler arası seçilim', ['Eşey içi fiziksel çatışma', 'Dallandırıcı doğal seçilim', 'Kalıtsal olmayan modifikasyon'], 'Bir eşeyin (çoğunlukla dişilerin) diğer eşeydeki bireyleri kur davranışları, ses veya görünüşlerine göre seçmesi eşeyler arası (interseksüel) seçilimdir.'),
  ('Üç seçilim türünden (yönlü, dengeleyici, dallandırıcı) hangisinin aynı coğrafi bölgede (simpatrik olarak) bir popülasyonu genetik olarak birbirinden uzaklaşan iki alt gruba ayırarak yeni türlerin oluşumuna (türleşmeye) yol açma potansiyeli en yüksektir?', 'Dallandırıcı seçilim', ['Dengeleyici seçilim', 'Yönlü seçilim', 'Klonlayıcı seçilim'], 'Dallandırıcı seçilim ara fenotipleri ve dolayısıyla iki uç grup arasındaki melezleri dezavantajlı kılarak gen akışının kesilmesine ve üreme yalıtımının gelişmesine zemin hazırlar.'),
  ('Doğal seçilim ile yapay seçilim mekanizmaları karşılaştırıldığında aşağıdakilerden hangisi her ikisi için de ortak bir özelliktir?', 'Başlangıçta popülasyonda var olan kalıtsal varyasyonlardan yararlanarak gen frekanslarını kuşaklar boyunca değiştirmeleri', ['Seçilen özelliklerin canlının vahşi doğadaki hayatta kalma ve avcılardan kaçma başarısını her zaman artırması', 'Önceden belirlenmiş ekonomik bir üretim hedefine ulaşmak için bilinçli çiftleştirme planları uygulanması', 'Yalnızca çevre etkisiyle oluşan kalıtsal olmayan modifikasyonların yavrulara aktarılmasına dayanması'], 'Hem doğal hem de yapay seçilim kalıtsal varyasyon üzerinde çalışır ve seçilen bireylerin diferansiyel üremesi yoluyla popülasyonun genetik yapısını (evrimsel olarak) değiştirir.'),
  ('Aslan sürülerinde erkeklerin boyunlarını çevreleyen gür ve koyu renkli yelenin vücut sıcaklığını artırmasına rağmen dişi aslanlar tarafından tercih edilmesi ve rakip erkekleri caydırması hangi iki mekanizmanın birleşik etkisidir?', 'Eşeyler arası seçilim ve eşey içi seçilim', ['Dengeleyici seçilim ve yapay seçilim', 'Dallandırıcı seçilim ve genetik sürüklenme', 'Çevresel modifikasyon ve yatay gen aktarımı'], 'Koyu ve gür yele hem erkek-erkek çatışmalarında boynu koruyup gücü simgeler (eşey içi seçilim) hem de dişilerce yüksek testosteron ve beslenme başarısı göstergesi olarak seçilir (eşeyler arası seçilim).'),
  ('Deniz iğnesi ve denizatı türlerinde dişilerin yumurtalarını erkeğin kuluçka kesesine bırakması ve embriyoları erkeğin besleyip doğurması sonucunda, doğada sınırlı kuluçka kesesi kapasitesi yüzünden dişilerin erkekler için birbiriyle rekabet ettiği görülür. Bu durum neyi doğrular?', 'Eşeysel seçilimin yönünün biyolojik cinsiyet etiketinden çok ebeveyn yatırımının büyüklüğüne bağlı olduğunu', ['Denizatlarında erkek bireylerin mayoz bölünmeyle yumurta, dişilerin ise sperm ürettiğini', 'Deniz suyunun tuzluluğunun balıklarda cinsiyet rollerini kalıtsal olmayan biçimde tersine çevirdiğini', 'Denizatlarının eşeyli üremeyi tamamen bırakarak tomurcuklanma ile eşeysiz çoğaldığını'], 'Erkek kuluçka kesesi üreme hızını sınırlayan kaynak haline geldiğinde roller tersine döner; dişiler süslenir ve erkeklerin kuluçka alanı için rekabet eder.'),
  ('Galapagos Adaları\'ndaki yer ispinozu (Geospiza fortis) popülasyonunda orta boy tohum üreten bitkilerin bir hastalıkla yok olup geriye yalnız çok küçük tohumlu otlar ile çok büyük sert tohumlu çalıların kalması, kuş popülasyonunun gaga büyüklüğü dağılımını nasıl etkiler?', 'Orta boy gagalı bireyler besin bulmakta zorlanıp elenirken küçük ve büyük gagalı uç fenotipler dallandırıcı seçilimle artar', ['Tüm ispinozların gagaları bir kuşak içinde tam orta büyüklükte birleşerek dengeleyici seçilimle sabitlenir', 'Kuşlar tohum yemeyi tamamen bırakıp deniz balıklarıyla beslenmek üzere perdeli ayaklar geliştirir', 'Gaga büyüklüğü kalıtsal olmadığı için tohum boyutundaki değişim kuş popülasyonunun gen havuzunu etkilemez'], 'Ara besin kaynağı çöktüğünde küçük gagalılar küçük tohumlarda, büyük gagalılar sert tohumlarda uzmanlaşır ve dallandırıcı seçilim popülasyonu iki uca ayırır.'),
  ('Bir gölde yaşayan dikenli balık (Gasterosteus aculeatus) popülasyonunda kıyıdaki sığ ve bitkili bölgede yaşayanların iri gövdeli ve geniş ağızlı olup dip omurgasızlarıyla beslendiği, açık ve derin suda yaşayanların ise ince uzun gövdeli ve dar ağızlı olup plankton süzdüğü; melezlerin ise her iki ortamda da verimsiz beslendiği belirlenmiştir. Bu durum neyin göstergesidir?', 'Farklı ekolojik nişlerin göl içinde dallandırıcı doğal seçilim yaratarak popülasyonu iki ayrı forma ayırdığının', ['Dengeleyici seçilimin kıyı ve açık su balıklarını tek bir ortalama vücut tipinde birleştirdiğinin', 'Balıkçıların oltayla yalnız orta boylu balıkları yakalayarak yapay seçilim uyguladığının', 'Su sıcaklığındaki mevsimsel farkların balık iskeletinde kalıtsal olmayan şekil değişikliği yaptığının'], 'Buzul sonrası göllerdeki üç dikenli balıkların "bentik" (dip) ve "limnetik" (açık su) formlara ayrılması doğadaki dallandırıcı seçilimin ve ekolojik türleşmenin en güçlü kanıtlarındandır.'),
  ('Yabani bademlerin tohumları ölümcül düzeyde siyanür (amigdalin) içerip çok acı olduğu halde, insanların tükettiği kültür bademlerinin tatlı ve zehirsiz olması nasıl gerçekleşmiştir?', 'Tek bir gen mutasyonuyla acılık maddesi üretmeyen nadir yabani ağaçların insanlarca fark edilip yapay seçilimle çoğaltılmasıyla', ['Yabani badem ağaçlarının toprağa şekerli su dökülerek sulanması sonucu meyvelerinin kalıcı olarak tatlanmasıyla', 'Kuşların doğada yalnız zehirli acı bademleri yiyip tatlı olanlara hiç dokunmamasıyla gerçekleşen doğal seçilimle', 'Badem tohumlarının güneşte kurutulurken içindeki siyanür genlerinin buharlaşarak yok olmasıyla'], 'Doğada acılık tohumu hayvanlara yenmekten koruyan bir adaptasyondur; ancak tek gen mutasyonuyla oluşan tatlı badem ağaçları insanlar tarafından seçilip tarıma alınmıştır.'),
  ('Bir bitki popülasyonunda çiçeklerin taç yaprak rengi kırmızı, pembe ve beyazdır. Bölgedeki arıların yalnız beyaz çiçekleri, sinek kuşlarının ise yalnız kırmızı çiçekleri ziyaret edip tozlaştırdığı; pembe çiçeklerin ise her iki tozlaştırıcı tarafından da çekici bulunmadığı saptanmıştır. Zamanla bu popülasyonda hangi değişim beklenir?', 'Dallandırıcı seçilim etkisiyle pembe çiçekli ara fenotip azalırken beyaz ve kırmızı çiçekli bireylerin oranı artar', ['Dengeleyici seçilim etkisiyle birkaç kuşak içinde tarladaki tüm çiçekler pembe renge dönüşür', 'Yönlü seçilim etkisiyle hem kırmızı hem beyaz çiçekler yok olup mavi çiçekli yeni bir tür oluşur', 'Tozlaştırıcı tercihinin bitkinin tohum bağlama başarısı üzerinde hiçbir seçici etkisi görülmez'], 'Tozlaştırıcıların iki uç rengi tercih edip ara rengi (pembe) ziyaret etmemesi üreme başarısını uçlara kaydırarak dallandırıcı seçilim oluşturur.'),
  ('Kuzey Amerika\'da yaşayan mavi gerdanlı kertenkelelerde (Uta stansburiana) turuncu boğazlı saldırgan erkeklerin geniş bölgeleri koruduğu, mavi boğazlı erkeklerin küçük bölgeleri savunduğu, sarı çizgili erkeklerin ise dişilere benzeyerek turuncu erkeklerin bölgesine gizlice girip çiftleştiği ve bu üç tipin "taş-kağıt-makas" döngüsüyle popülasyonda korunduğu görülmüştür. Bu durum neyi gösterir?', 'Eşeysel seçilimin her zaman tek bir "en iyi" erkek tipini sabitlemeyip frekansa bağlı seçilimle çoklu varyasyonu koruyabildiğini', ['Kertenkelelerde boğaz renginin yaşlandıkça turuncudan maviye ve sarıya doğru sırayla değiştiğini', 'Dengeleyici seçilimin üç renk tipini de yok ederek tek renkli yeşil erkekleri hakim kıldığını', 'Sarı boğazlı erkeklerin kısır olduğunu ve popülasyona hiçbir genetik katkı yapamadığını'], 'Hangi erkek tipi çoğalırsa onun zayıf noktasını kullanan diğer strateji avantaj kazanır (negatif frekansa bağlı eşeysel seçilim); böylece genetik çeşitlilik korunur.'),
  ('Aşağıdaki örneklerden hangisi dallandırıcı (çeşitlendirici) doğal seçilimi diğer seçilim türlerinden ayıran en net senaryodur?', 'Açık renkli kum ve siyah kayalıklardan oluşan yamalı bir arazide açık ve siyah salyangozların korunup kahverengi ara formların kuşlarca avlanması', ['Karlı bir kış mevsiminde küçük ve zayıf serçeler ile aşırı iri serçelerin donarak ölmesi ve orta boylu serçelerin sağ kalması', 'Orman yangınlarından sonra hızla büyüyen uzun boylu çam fidanlarının kısa boyluları gölgede bırakarak baskınlaşması', 'Çiftçilerin daha tatlı meyve veren elma ağaçlarından aşı kalemi alarak bahçedeki tüm ağaçları aynı çeşide dönüştürmesi'], 'Yamalı (heterojen) habitatlarda iki zıt zemine uyan uç fenotipler korunurken hiçbir zeminde gizlenemeyen ara form elenir; bu dallandırıcı seçilimdir.'),
  ('Dulavratotu veya tavus kuşu gibi türlerde erkeklerin yavru bakımına hiç katılmayıp yalnızca sperm verdiği durumlarda bile dişilerin eş seçiminde son derece titiz ve seçici davranmasının evrimsel açıklaması nedir?', 'Dişinin yavrularının hayatta kalma ve gelecekteki üreme şansını artıracak yüksek kalıtsal kaliteye ("iyi genlere") sahip babayı seçmesi', ['Dişilerin çiftleşme sonrasında erkekten besin veya yuva yardımı alacağını yanlışlıkla ümit etmesi', 'Erkeklerin hepsinin genetik olarak birbirinin kopyası olması nedeniyle seçimin tamamen rastgele yapılması', 'Dişilerin yalnız kendilerinden daha küçük ve hastalıklı erkekleri seçerek rekabeti azaltmak istemesi'], 'Erkeğin maddi kaynak veya bakım sunmadığı (lek sistemi) türlerde dişi seçiciliğinin temel getirisi dolaylı genetik faydadır: Yavrular babadan hem yüksek yaşam gücü hem de çekicilik genlerini alır.'),
  ('Gül, lale ve orkide yetiştiricilerinin doğada çok nadir rastlanan katmerli veya alışılmadık renkli çiçekleri seçip doku kültürü ve çaprazlamayla ticari olarak çoğaltması neden "doğal seçilim" olarak adlandırılamaz?', 'Katmerli çiçeklerin çoğunda üreme organları taç yaprağa dönüştüğü için doğada kısır kalıp elenecekken yalnızca insan müdahalesiyle yaşatıldığı için', ['Süs bitkilerinde renk ve yaprak şeklini belirleyen genlerin DNA yerine hücre çeperindeki selülozda taşınması nedeniyle', 'Doğal seçilimin çiçekli bitkiler aleminde hiçbir zaman gerçekleşmeyip yalnız hayvanlar aleminde görülmesi nedeniyle', 'Çiçek renklerinin yalnız vazodaki suya katılan gıda boyalarıyla oluşturulan modifikasyonlar olması nedeniyle'], 'Katmerli güllerde erkek organlar taç yaprağa dönüşmüştür, doğada tozlaşma ve tohum verimi çok düşüktür; bu özelliğin yayılması ekolojik uyum değil insan beğenisi (yapay seçilim) sonucudur.'),
  ('Cennet kuşları ve tavus kuşu gibi aşırı süslü erkeklere sahip türlerin genellikle yırtıcı memelilerin az, meyve gibi besinlerin ise bol olduğu tropikal adalarda veya ormanlarda evrimleşmiş olmasının ekolojik nedeni nedir?', 'Besin bolluğu ve düşük avcı baskısının, hayatta kalma maliyetini hafifleterek eşeysel seçilimin abartılı süsler üretmesine geniş alan tanıması', ['Tropikal bölgelerdeki yüksek nem oranının kuş tüylerini genetik değişim olmadan kendiliğinden renklendirmesi', 'Soğuk kuşaklarda yaşayan kuşların hiçbirinde eşeyli üreme ve dişi tercihi davranışlarının görülmemesi', 'Yerli halkların tropikal ormanlardaki tüm kuşları kafeslere alıp yapay seçilimle boyamış olması'], 'Doğal seçilim (besin bulma zorluğu ve yırtıcı tehlikesi) çok sert olduğunda abartılı süsleri sınırlar; ekolojik koşullar rahatladığında eşeysel seçilim üzerindeki fren kalkar.'),
  ('Bir göldeki kurbağa popülasyonunda dişiler "kalın ve pes" sesle öten iri erkekleri çiftleşmek için seçerken, bölgedeki kurbağa yiyen yarasaların da aynı kalın sesi takip ederek iri erkekleri daha çok avladığı belirlenmiştir. Uzun vadede erkek kurbağaların ses frekansı ve boyutu nasıl şekillenir?', 'Eşeysel seçilim ile doğal seçilimin zıt yönlü baskıları birbirini dengeleyerek orta kalınlıkta ses ve boyutta kararlı bir uzlaşma noktası oluşturur', ['Yarasalar tüm kurbağaları bir haftada tüketerek türün soyunu kesin olarak sona erdirir', 'Erkek kurbağalar ses tellerini kopararak eşeysiz üremeye geçer ve dişilere ihtiyaç duymaz', 'Dallandırıcı seçilimle kurbağaların yarısı balığa yarısı kertenkeleye dönüşerek gölden ayrılır'], 'Orta Amerika\'daki Tungara kurbağalarında (Physalaemus pustulosus) incelenen bu klasik durumda dişi tercihi karmaşık/pes sesi iterken yarasa avcılığı karşı yönden bastırır ve ara bir optimumda denge kurulur.'),
  ('Bir popülasyonda dallandırıcı seçilimin uzun süre kesintisiz işlemesi durumunda genetik varyasyon miktarında nasıl bir değişim gözlenir?', 'İki farklı uçtaki aleller birlikte korunduğu için popülasyonun toplam genetik ve fenotipik varyasyonu yüksek kalır veya artar', ['Yalnızca tek bir alel sabitlendiği için popülasyondaki genetik varyasyon kısa sürede sıfıra iner', 'Sadece heterozigot genotipli bireyler yaşadığı için fenotipik çeşitlilik tek bir ortalamada daralır', 'Kromozomlardaki tüm genler mutasyona uğramayı bıraktığı için gen havuzu tamamen donar'], 'Dengeleyici ve yönlü seçilim genellikle fenotipik dağılımı daraltıp belirli alelleri elerken, dallandırıcı seçilim birden fazla uç fenotipi koruyarak polimorfizmi (çok biçimliliği) sürdürür.'),
  ('Bir böcek popülasyonunda vücut büyüklüğü ortalaması 10 mm\'dir. Bölgeye yerleşen bir kuş türünün yalnızca 9-11 mm arasındaki böcekleri avlayacak gaga yapısına sahip olduğu, 7 mm\'lik küçük böcekleri göremediği ve 13 mm\'lik büyük böcekleri ise yutamadığı gözlenmiştir. Birkaç kuşak sonra böcek popülasyonunda hangi değişim beklenir?', 'Dallandırıcı seçilim sonucu 10 mm\'lik ara boylar azalırken 7 mm ve 13 mm civarındaki bireylerin sıklığı artar', ['Dengeleyici seçilim sonucu tüm böcekler 10 mm boyunda sabitlenerek kuşlara kolay yem olur', 'Yönlü seçilim sonucu yalnızca 10 mm\'lik böcekler çoğalır ve diğer tüm boylar yok olur', 'Böcekler kuş gagasından kaçmak için bir hafta içinde kanatlarını dökerek toprağın altına gömülür'], 'Avcının tam ortalama boydaki bireyleri hedef alıp her iki uç boyu avlayamaması, popülasyonu küçük ve büyük uçlara doğru bölen tipik bir dallandırıcı seçilim baskısıdır.'),
  ('Afrika\'daki bazı antilop türlerinde (örneğin kob antilopları) üreme mevsiminde erkeklerin besin veya su bulunmayan küçük bir düzlüğe ("lek alanı") toplanarak merkezdeki en iyi noktayı tutmak için mücadele ettiği, dişilerin ise bu alana gelip merkezdeki baskın erkeklerle çiftleştikten sonra ayrıldığı görülür. Bu sistem hangi seçilim mekanizmasının klasik bir modelidir?', 'Hem erkek-erkek rekabetini hem de dişi tercihini bir arada barındıran eşeysel seçilimin', ['Popülasyondaki tüm erkeklere eşit çiftleşme şansı tanıyan dengeleyici seçilimin', 'Avcıların antilopları kolayca yakalaması için geliştirilmiş yapay seçilimin', 'Besin kıtlığı nedeniyle boynuzların küçüldüğü çevresel modifikasyonun'], 'Lek üreme sisteminde merkezdeki dar alanı tutmak şiddetli eşey içi rekabeti, dişilerin merkeze ulaşabilmiş sağlıklı erkekleri seçmesi ise eşeyler arası seçilimi aynı anda sergiler.'),
];
